def ensure_bundled_rtl_vendor() -> str:
    target_dir = RUNTIME_VENDOR_DIR
    try:
        os.makedirs(target_dir, exist_ok=True)
    except Exception:
        target_dir = os.path.join(os.path.expanduser("~"), "pystation_rtl_vendor")
        try:
            os.makedirs(target_dir, exist_ok=True)
        except Exception:
            return ""
    try:
        for rel_path, payload in EMBEDDED_RTL_VENDOR_Z.items():
            out_path = os.path.join(target_dir, *rel_path.split('/'))
            folder = os.path.dirname(out_path)
            if folder:
                os.makedirs(folder, exist_ok=True)
            if not os.path.isfile(out_path) or os.path.getsize(out_path) < 20:
                raw = zlib.decompress(base64.b64decode(payload.encode('ascii'))).decode('utf-8')
                with open(out_path, 'w', encoding='utf-8') as fh:
                    fh.write(raw)
    except Exception:
        return ""
    return target_dir

BUNDLED_VENDOR_DIR = ensure_bundled_rtl_vendor()
for extra in (BUNDLED_VENDOR_DIR, VENDOR_DIR):
    if extra and os.path.isdir(extra) and extra not in sys.path:
        sys.path.insert(0, extra)

try:
    import arabic_reshaper
except Exception:
    arabic_reshaper = None

try:
    from bidi.algorithm import get_display as bidi_get_display
except Exception:
    bidi_get_display = None


def _first_existing(*paths: str) -> str:
    for path in paths:
        if path and os.path.exists(path):
            return path
    return ""


def has_rtl_text(text) -> bool:
    if text is None:
        return False
    for ch in str(text):
        code = ord(ch)
        if 0x0590 <= code <= 0x08FF or 0xFB50 <= code <= 0xFDFF or 0xFE70 <= code <= 0xFEFF:
            return True
    return False


def repair_mojibake_text(text) -> str:
    src = "" if text is None else str(text)
    if not src:
        return src
    if not any(ch in src for ch in "ÙØÚÛÃ"): 
        return src
    try:
        fixed = src.encode("latin-1").decode("utf-8")
        if has_rtl_text(fixed):
            return fixed
    except Exception:
        pass
    return src


def display_text(text) -> str:
    src = repair_mojibake_text(text)
    if not src:
        return src
    if has_rtl_text(src) and arabic_reshaper is not None and bidi_get_display is not None:
        try:
            return bidi_get_display(arabic_reshaper.reshape(src))
        except Exception:
            pass
    return src


