def _write_binary_if_missing(path: str, payload_b64_z: str) -> bool:
    try:
        if path and os.path.isfile(path) and os.path.getsize(path) > 10000:
            return True
    except Exception:
        pass
    try:
        folder = os.path.dirname(path)
        if folder:
            os.makedirs(folder, exist_ok=True)
        raw = zlib.decompress(base64.b64decode(payload_b64_z.encode("ascii")))
        with open(path, "wb") as fh:
            fh.write(raw)
        return True
    except Exception:
        return False


def ensure_bundled_vazirmatn() -> Tuple[str, str]:
    target_dir = FONT_DIR
    try:
        os.makedirs(target_dir, exist_ok=True)
    except Exception:
        target_dir = os.path.join(os.path.expanduser("~"), "pystation_fonts")
        try:
            os.makedirs(target_dir, exist_ok=True)
        except Exception:
            return "", ""
    reg_path = os.path.join(target_dir, "Vazirmatn-Regular.ttf")
    bold_path = os.path.join(target_dir, "Vazirmatn-Bold.ttf")
    _write_binary_if_missing(reg_path, EMBEDDED_VAZIRMATN_REGULAR_Z)
    _write_binary_if_missing(bold_path, EMBEDDED_VAZIRMATN_BOLD_Z)
    return reg_path, bold_path


BUNDLED_REGULAR_FONT, BUNDLED_BOLD_FONT = ensure_bundled_vazirmatn()

DEFAULT_APP_FONT = "Roboto"
APP_FONT = DEFAULT_APP_FONT
APP_FONT_REGULAR = _first_existing(
    BUNDLED_REGULAR_FONT,
    os.path.join(FONT_DIR, "Vazirmatn-Regular.ttf"),
    os.path.join(BASE_DIR, "Vazirmatn-Regular.ttf"),
    "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
)
APP_FONT_BOLD = _first_existing(
    BUNDLED_BOLD_FONT,
    os.path.join(FONT_DIR, "Vazirmatn-Bold.ttf"),
    os.path.join(BASE_DIR, "Vazirmatn-Bold.ttf"),
    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
    APP_FONT_REGULAR,
)
APP_FONT_READY = False
if APP_FONT_REGULAR and os.path.exists(APP_FONT_REGULAR):
    try:
        LabelBase.register(name="VazirmatnUI", fn_regular=APP_FONT_REGULAR, fn_bold=(APP_FONT_BOLD or APP_FONT_REGULAR))
        APP_FONT = "VazirmatnUI"
        APP_FONT_READY = True
    except Exception:
        APP_FONT = DEFAULT_APP_FONT
        APP_FONT_READY = False


class FaLabel(KivyLabel):
    def __init__(self, **kw):
        self._fa_guard = True
        kw.setdefault("font_name", APP_FONT)
        super().__init__(**kw)
        self._fa_guard = False
        self._apply_display_shape()

    def _apply_display_shape(self):
        current = self.text
        shaped = display_text(current)
        if shaped != current:
            self._fa_guard = True
            try:
                self.text = shaped
            finally:
                self._fa_guard = False

    def on_text(self, _instance, value):
        if getattr(self, "_fa_guard", False):
            return
        shaped = display_text(value)
        if shaped != value:
            self._fa_guard = True
            try:
                self.text = shaped
            finally:
                self._fa_guard = False


