def normalize_font_ref(font_ref: str) -> str:
    ref = str(font_ref or "").strip()
    if ref and os.path.isfile(ref):
        return os.path.abspath(ref)
    if APP_FONT:
        return APP_FONT
    return DEFAULT_APP_FONT


def resolve_font_name(font_ref: str, bold: bool = False) -> Tuple[str, bool]:
    ref = normalize_font_ref(font_ref)
    known_vazir_paths = {
        os.path.abspath(path) for path in (APP_FONT_REGULAR, APP_FONT_BOLD, BUNDLED_REGULAR_FONT, BUNDLED_BOLD_FONT)
        if path and os.path.isfile(path)
    }
    if ref == APP_FONT:
        return APP_FONT, bool(bold)
    if os.path.isfile(ref):
        abs_ref = os.path.abspath(ref)
        base = os.path.basename(abs_ref).lower()
        if abs_ref in known_vazir_paths or "vazirmatn" in base:
            return APP_FONT, bool(bold)
        if bold:
            folder = os.path.dirname(abs_ref)
            stem, ext = os.path.splitext(os.path.basename(abs_ref))
            cands = []
            if "regular" in stem.lower():
                cands.append(stem.replace("Regular", "Bold").replace("regular", "Bold") + ext)
            if stem.lower().endswith("-r"):
                cands.append(stem[:-2] + "-Bold" + ext)
            cands.append(stem + "-Bold" + ext)
            cands.append(stem + " Bold" + ext)
            for cand in cands:
                cand_path = os.path.join(folder, cand)
                if os.path.isfile(cand_path):
                    return os.path.abspath(cand_path), False
    return ref, False


def estimate_text_world_box(text, font_size: float) -> Tuple[float, float]:
    size = max(1.0, float(font_size))
    lines = str(text or "").splitlines() or [""]
    shown_lines = [display_text(repair_mojibake_text(line)) for line in lines]
    max_chars = max((len(line) for line in shown_lines), default=1)
    width = max(size * 0.90, max_chars * size * 0.62)
    height = max(size * 1.35, len(lines) * size * 1.45)
    return width, height


def text_rect_from_anchor(ax: float, ay: float, w: float, h: float, align: str = "right") -> Tuple[float, float, float, float]:
    width = max(1.0, float(w))
    height = max(1.0, float(h))
    mode = str(align or "right").lower()
    if mode == "left":
        left, right = ax, ax + width
    elif mode == "center":
        left, right = ax - width * 0.5, ax + width * 0.5
    else:
        left, right = ax - width, ax
    bottom = ay - height * 0.5
    top = ay + height * 0.5
    return left, bottom, right, top


def list_available_font_choices() -> List[Tuple[str, str]]:
    entries: List[Tuple[str, str]] = []
    seen = set()

    def add(label: str, ref: str):
        key = os.path.abspath(ref) if ref and os.path.isfile(ref) else str(ref)
        if not ref or key in seen:
            return
        seen.add(key)
        entries.append((label, ref))

    if BUNDLED_REGULAR_FONT and os.path.isfile(BUNDLED_REGULAR_FONT):
        add("Vazir Reg", BUNDLED_REGULAR_FONT)
    if BUNDLED_BOLD_FONT and os.path.isfile(BUNDLED_BOLD_FONT):
        add("Vazir Bold", BUNDLED_BOLD_FONT)
    add("UI Default", APP_FONT)

    search_dirs = [FONT_DIR, BASE_DIR, "/storage/emulated/0/Download", "/sdcard/Download"]
    for folder in search_dirs:
        if not folder or not os.path.isdir(folder):
            continue
        for pattern in ("*.ttf", "*.TTF", "*.otf", "*.OTF"):
            for path in sorted(glob.glob(os.path.join(folder, pattern))):
                name = os.path.splitext(os.path.basename(path))[0]
                if os.path.abspath(path) == os.path.abspath(BUNDLED_REGULAR_FONT or "") and name.lower().startswith("vazirmatn"):
                    continue
                if os.path.abspath(path) == os.path.abspath(BUNDLED_BOLD_FONT or "") and name.lower().startswith("vazirmatn"):
                    continue
                add(name, os.path.abspath(path))
    return entries or [("UI Default", APP_FONT)]


def install_font_file_to_project(src_path: str) -> Tuple[bool, str, str]:
    src = str(src_path or "").strip().strip('"').strip("'")
    if not src:
        return False, "Enter a font path first", ""
    if not os.path.isfile(src):
        return False, "Font file not found", ""
    ext = os.path.splitext(src)[1].lower()
    if ext not in (".ttf", ".otf"):
        return False, "Only TTF / OTF fonts are supported", ""
    try:
        os.makedirs(FONT_DIR, exist_ok=True)
        dst = os.path.join(FONT_DIR, os.path.basename(src))
        if os.path.abspath(src) != os.path.abspath(dst):
            shutil.copy2(src, dst)
        return True, f"Font installed: {os.path.basename(dst)}", os.path.abspath(dst)
    except Exception as exc:
        return False, f"Install failed: {exc}", ""

ANDROID_PY_DIR_CANDIDATES = [
    "/storage/emulated/0/py",
    "/sdcard/py",
    "/storage/self/primary/py",
]

def resolve_user_py_dir() -> str:
    for path in ANDROID_PY_DIR_CANDIDATES:
        try:
            if os.path.isdir(path):
                return path
        except Exception:
            pass
    for path in ANDROID_PY_DIR_CANDIDATES:
        try:
            os.makedirs(path, exist_ok=True)
            return path
        except Exception:
            pass
    return os.path.join(os.path.expanduser("~"), "py")

# ===== UTM Conversion =====
class UTMConverter:
    """UTM <-> Geographic coordinate conversion (WGS84)."""

    @staticmethod
    def lat_lon_to_utm(lat: float, lon: float, zone: Optional[int] = None) -> Tuple[float, float, int, str]:
        a = 6378137.0
        e = 0.081819191
        k0 = 0.9996

        lat_rad = math.radians(lat)
        lon_rad = math.radians(lon)

        if zone is None:
            zone = int((lon + 180) / 6) + 1

        zone_letter = 'N' if lat >= 0 else 'S'
        lon0 = (zone - 1) * 6 - 180 + 3
        lon0_rad = math.radians(lon0)

        N = a / math.sqrt(1 - e * e * math.sin(lat_rad) * math.sin(lat_rad))
        T = math.tan(lat_rad) * math.tan(lat_rad)
        C = (e * e / (1 - e * e)) * math.cos(lat_rad) * math.cos(lat_rad)
        A = (lon_rad - lon0_rad) * math.cos(lat_rad)

        e2 = e * e
        e4 = e2 * e2
        e6 = e4 * e2

        M = a * ((1 - e2 / 4 - 3 * e4 / 64 - 5 * e6 / 256) * lat_rad
                 - (3 * e2 / 8 + 3 * e4 / 32 + 45 * e6 / 1024) * math.sin(2 * lat_rad)
                 + (15 * e4 / 256 + 45 * e6 / 1024) * math.sin(4 * lat_rad)
                 - (35 * e6 / 3072) * math.sin(6 * lat_rad))

        easting = k0 * N * (A + (1 - T + C) * A**3 / 6 +
                            (5 - 18 * T + T * T + 72 * C - 58 * (e * e / (1 - e * e))) * A**5 / 120) + 500000.0

        northing = k0 * (M + N * math.tan(lat_rad) *
                         (A**2 / 2 + (5 - T + 9 * C + 4 * C * C) * A**4 / 24 +
                          (61 - 58 * T + T * T + 600 * C - 330 * (e * e / (1 - e * e))) * A**6 / 720))

        if lat < 0:
            northing += 10000000.0

        return easting, northing, zone, zone_letter

    @staticmethod
    def utm_to_lat_lon(easting: float, northing: float, zone: int, hemisphere: str = 'N') -> Tuple[float, float]:
        a = 6378137.0
        e = 0.081819191
        k0 = 0.9996

        x = easting - 500000.0
        y = northing - 10000000.0 if str(hemisphere).upper().startswith('S') else northing
        lon0 = (zone - 1) * 6 - 180 + 3

        e2 = e * e
        e4 = e2 * e2
        e6 = e4 * e2

        M = y / k0
        mu = M / (a * (1 - e2 / 4 - 3 * e4 / 64 - 5 * e6 / 256))
        e1 = (1 - math.sqrt(1 - e2)) / (1 + math.sqrt(1 - e2))

        lat1 = (mu
                + (3 * e1 / 2 - 27 * e1**3 / 32) * math.sin(2 * mu)
                + (21 * e1 * e1 / 16 - 55 * e1**4 / 32) * math.sin(4 * mu)
                + (151 * e1**3 / 96) * math.sin(6 * mu)
                + (1097 * e1**4 / 512) * math.sin(8 * mu))

        C1 = (e2 / (1 - e2)) * math.cos(lat1) * math.cos(lat1)
        T1 = math.tan(lat1) * math.tan(lat1)
        N1 = a / math.sqrt(1 - e2 * math.sin(lat1) * math.sin(lat1))
        R1 = a * (1 - e2) / math.pow(1 - e2 * math.sin(lat1) * math.sin(lat1), 1.5)
        D = x / (N1 * k0)

        lat = lat1 - (N1 * math.tan(lat1) / R1) * (
            D * D / 2
            - (5 + 3 * T1 + 10 * C1 - 4 * C1 * C1 - 9 * (e2 / (1 - e2))) * D**4 / 24
            + (61 + 90 * T1 + 298 * C1 + 45 * T1 * T1 - 252 * (e2 / (1 - e2)) - 3 * C1 * C1) * D**6 / 720
        )

        lon = (D - (1 + 2 * T1 + C1) * D**3 / 6 +
               (5 - 2 * C1 + 28 * T1 - 3 * C1 * C1 + 8 * (e2 / (1 - e2)) + 24 * T1 * T1) * D**5 / 120) / math.cos(lat1)

        return math.degrees(lat), math.degrees(lon) + lon0

# ===== Error Logging =====
def log_error(context: str = "") -> None:
    text = f"### {context}\n{traceback.format_exc()}\n{'-' * 60}\n"
    try:
        log_path = os.path.join(os.path.expanduser("~"), "pystation_crash.txt")
        with open(log_path, "a", encoding="utf-8") as fh:
            fh.write(text)
        print(f"Error logged to: {log_path}")
    except Exception:
        pass
    print(text)

def safe(fn):
    @wraps(fn)
    def wrapper(self, *args, **kwargs):
        try:
            return fn(self, *args, **kwargs)
        except Exception as e:
            log_error(f"{fn.__name__}: {str(e)}")
            try:
                self.status_text = f"ERROR in {fn.__name__}"
            except Exception:
                pass
            return False
    return wrapper

class KeepAlive(ExceptionHandler):
    def handle_exception(self, inst):
        log_error("ExceptionManager")
        return ExceptionManager.PASS

ExceptionManager.add_handler(KeepAlive())

# ===== Geometry Functions =====
def dist(x1, y1, x2, y2) -> float:
    return math.hypot(x2 - x1, y2 - y1)

def ang(x1, y1, x2, y2) -> float:
    return math.degrees(math.atan2(y2 - y1, x2 - x1)) % 360.0

def rot_point(x, y, px, py, deg) -> Tuple[float, float]:
    r = math.radians(deg)
    c, s = math.cos(r), math.sin(r)
    dx, dy = x - px, y - py
    return px + dx * c - dy * s, py + dx * s + dy * c

def seg_distance(px, py, x1, y1, x2, y2) -> float:
    ln = dist(x1, y1, x2, y2)
    if ln < 1e-6:
        return dist(px, py, x1, y1)
    t = ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / (ln * ln)
    t = max(0.0, min(1.0, t))
    return dist(px, py, x1 + t * (x2 - x1), y1 + t * (y2 - y1))

def project_to_segment(px, py, x1, y1, x2, y2) -> Tuple[float, float, float, float]:
    dx = x2 - x1
    dy = y2 - y1
    den = dx * dx + dy * dy
    if den <= 1e-12:
        return x1, y1, 0.0, dist(px, py, x1, y1)
    t = ((px - x1) * dx + (py - y1) * dy) / den
    t = max(0.0, min(1.0, t))
    qx = x1 + t * dx
    qy = y1 + t * dy
    return qx, qy, t, dist(px, py, qx, qy)

def seg_intersection(x1, y1, x2, y2, x3, y3, x4, y4) -> Optional[Tuple[float, float]]:
    den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if abs(den) < 1e-12:
        return None
    t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / den
    u = ((x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)) / den
    if 0.0 <= t <= 1.0 and 0.0 <= u <= 1.0:
        return x1 + t * (x2 - x1), y1 + t * (y2 - y1)
    return None

def angle_in_ccw(a, start, end) -> bool:
    span = (end - start) % 360.0
    if span < 1e-9:
        span = 360.0
    return ((a - start) % 360.0) <= span

def _unit(dx, dy) -> Tuple[float, float]:
    n = math.hypot(dx, dy)
    if n < 1e-12:
        return 0.0, 0.0
    return dx / n, dy / n

def clamp(v: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, v))

SNAP_RADIUS = 34.0
SNAP_STICK_RADIUS = 64.0
PICK_RADIUS = 16.0
SNAP_END_HARDLOCK_PX = 30.0
SNAP_INT_HARDLOCK_PX = 22.0

# ===== Data Classes =====
@dataclass(eq=False)
class BaseItem:
    color: Tuple[float, float, float, float] = (1.0, 1.0, 1.0, 1.0)
    width: float = 2.0
    layer_name: str = "Default"

@dataclass(eq=False)
class LineItem(BaseItem):
    x1: float = 0.0
    y1: float = 0.0
    x2: float = 0.0
    y2: float = 0.0

@dataclass(eq=False)
class CircleItem(BaseItem):
    cx: float = 0.0
    cy: float = 0.0
    r: float = 1.0

@dataclass(eq=False)
class ArcItem(BaseItem):
    cx: float = 0.0
    cy: float = 0.0
    r: float = 1.0
    a_start: float = 0.0
    a_end: float = 90.0

@dataclass(eq=False)
class RectItem(BaseItem):
    x1: float = 0.0
    y1: float = 0.0
    x2: float = 0.0
    y2: float = 0.0
    rotation: float = 0.0

@dataclass(eq=False)
class PolyItem(BaseItem):
    cx: float = 0.0
    cy: float = 0.0
    r: float = 1.0
    sides: int = 6
    rotation: float = 0.0

@dataclass(eq=False)
class BoundaryItem(BaseItem):
    pts: List[float] = field(default_factory=list)
    closed: bool = True

@dataclass(eq=False)
class TextItem(BaseItem):
    x: float = 0.0
    y: float = 0.0
    text: str = ""
    font_ref: str = ""
    font_size: float = 24.0
    rotation: float = 0.0
    text_w: float = 24.0
    text_h: float = 24.0
    align: str = "right"
    bold: bool = False

# ===== Boundary Helpers =====
def boundary_count(b: BoundaryItem) -> int:
    return len(b.pts) // 2

def boundary_get(b: BoundaryItem, i: int) -> Tuple[float, float]:
    n = boundary_count(b)
    i %= n
    return b.pts[2 * i], b.pts[2 * i + 1]

def boundary_edges(b: BoundaryItem):
    n = boundary_count(b)
    m = n if b.closed else n - 1
    for i in range(m):
        j = (i + 1) % n
        yield b.pts[2 * i], b.pts[2 * i + 1], b.pts[2 * j], b.pts[2 * j + 1]

def boundary_area(b: BoundaryItem) -> float:
    if not b.closed:
        return 0.0
    n = boundary_count(b)
    if n < 3:
        return 0.0
    s = 0.0
    for x1, y1, x2, y2 in boundary_edges(b):
        s += x1 * y2 - x2 * y1
    return abs(s) * 0.5

def boundary_centroid(b: BoundaryItem) -> Tuple[float, float]:
    n = boundary_count(b)
    if b.closed and n >= 3:
        a = cx = cy = 0.0
        for x1, y1, x2, y2 in boundary_edges(b):
            cr = x1 * y2 - x2 * y1
            a += cr
            cx += (x1 + x2) * cr
            cy += (y1 + y2) * cr
        a *= 0.5
        if abs(a) > 1e-9:
            return cx / (6.0 * a), cy / (6.0 * a)
    if n == 0:
        return 0.0, 0.0
    return sum(b.pts[0::2]) / n, sum(b.pts[1::2]) / n

def edge_azimuth(x1, y1, x2, y2) -> float:
    return (90.0 - ang(x1, y1, x2, y2)) % 360.0

def vertex_label_dir(b: BoundaryItem, i: int) -> Tuple[float, float]:
    n = boundary_count(b)
    x, y = b.pts[2 * i], b.pts[2 * i + 1]
    has_prev = b.closed or i > 0
    has_next = b.closed or i < n - 1
    d1 = d2 = (0.0, 0.0)
    if has_prev:
        px, py = b.pts[2 * (i - 1)], b.pts[2 * (i - 1) + 1]
        d1 = _unit(x - px, y - py)
    if has_next:
        j = (i + 1) % n
        d2 = _unit(b.pts[2 * j] - x, b.pts[2 * j + 1] - y)
    if has_prev and has_next:
        bx, by = d1[0] - d2[0], d1[1] - d2[1]
    elif has_prev:
        bx, by = d1
    else:
        bx, by = -d2[0], -d2[1]
    m = math.hypot(bx, by)
    if m < 1e-6:
        d = d2 if has_next else d1
        bx, by = -d[1], d[0]
        m = math.hypot(bx, by)
    bx, by = bx / m, by / m
    if b.closed and n >= 3:
        cx, cy = boundary_centroid(b)
        if (x - cx) * bx + (y - cy) * by < 0:
            bx, by = -bx, -by
    return bx, by

def edge_label_geom(x1, y1, x2, y2) -> Tuple[float, float, float]:
    theta = ang(x1, y1, x2, y2)
    read = theta + 180.0 if 90.0 < theta <= 270.0 else theta
    r = math.radians(read)
    return read % 360.0, math.cos(r + math.pi / 2.0), math.sin(r + math.pi / 2.0)

# ===== Item Helper Functions =====
def _text_anchor_to_center_offset(it: TextItem) -> Tuple[float, float]:
    align = str(getattr(it, "align", "right") or "right").lower()
    half_w = max(1.0, float(getattr(it, "text_w", 1.0))) * 0.5
    if align == "left":
        return half_w, 0.0
    if align == "center":
        return 0.0, 0.0
    return -half_w, 0.0

def item_center(it) -> Tuple[float, float]:
    if isinstance(it, BoundaryItem):
        return boundary_centroid(it)
    if isinstance(it, TextItem):
        ox, oy = _text_anchor_to_center_offset(it)
        return rot_point(it.x + ox, it.y + oy, it.x, it.y, getattr(it, "rotation", 0.0))
    if isinstance(it, (LineItem, RectItem)):
        return (it.x1 + it.x2) * 0.5, (it.y1 + it.y2) * 0.5
    return it.cx, it.cy

def item_bounds(it) -> Tuple[float, float, float, float]:
    if isinstance(it, BoundaryItem):
        if not it.pts:
            return 0, 0, 0, 0
        return min(it.pts[0::2]), min(it.pts[1::2]), max(it.pts[0::2]), max(it.pts[1::2])
    if isinstance(it, LineItem):
        return min(it.x1, it.x2), min(it.y1, it.y2), max(it.x1, it.x2), max(it.y1, it.y2)
    if isinstance(it, (CircleItem, ArcItem)):
        return it.cx - it.r, it.cy - it.r, it.cx + it.r, it.cy + it.r
    if isinstance(it, RectItem):
        corners = rect_corners(it)
        xs = [corners[i] for i in range(0, 8, 2)]
        ys = [corners[i] for i in range(1, 8, 2)]
        return min(xs), min(ys), max(xs), max(ys)
    if isinstance(it, PolyItem):
        pts = poly_points(it)
        xs = [pts[i] for i in range(0, len(pts), 2)]
        ys = [pts[i] for i in range(1, len(pts), 2)]
        return min(xs), min(ys), max(xs), max(ys)
    if isinstance(it, TextItem):
        corners = text_corners(it)
        xs = [corners[i] for i in range(0, 8, 2)]
        ys = [corners[i] for i in range(1, 8, 2)]
        return min(xs), min(ys), max(xs), max(ys)
    return 0, 0, 0, 0

def rect_corners(it: RectItem) -> List[float]:
    cx, cy = item_center(it)
    hw, hh = abs(it.x2 - it.x1) * 0.5, abs(it.y2 - it.y1) * 0.5
    pts: List[float] = []
    for dx, dy in ((-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh)):
        x, y = rot_point(cx + dx, cy + dy, cx, cy, it.rotation)
        pts.extend([x, y])
    return pts

def poly_points(it: PolyItem) -> List[float]:
    pts: List[float] = []
    n = max(3, int(it.sides))
    for i in range(n):
        a = math.radians(i * 360.0 / n + it.rotation)
        pts.extend([it.cx + it.r * math.cos(a), it.cy + it.r * math.sin(a)])
    return pts

def arc_kivy_angles(it: ArcItem) -> Tuple[float, float]:
    a1 = 90.0 - it.a_end
    a2 = 90.0 - it.a_start
    while a2 <= a1:
        a2 += 360.0
    return a1, a2

def text_corners(it: TextItem) -> List[float]:
    cx, cy = item_center(it)
    hw = max(1.0, float(it.text_w)) * 0.5
    hh = max(1.0, float(it.text_h)) * 0.5
    pts: List[float] = []
    for px, py in ((cx - hw, cy - hh), (cx + hw, cy - hh), (cx + hw, cy + hh), (cx - hw, cy + hh)):
        x, y = rot_point(px, py, cx, cy, getattr(it, "rotation", 0.0))
        pts.extend([x, y])
    return pts

def item_translate(it, dx, dy) -> None:
    if isinstance(it, BoundaryItem):
        for i in range(0, len(it.pts), 2):
            it.pts[i] += dx
            it.pts[i + 1] += dy
    elif isinstance(it, TextItem):
        it.x += dx
        it.y += dy
    elif isinstance(it, (LineItem, RectItem)):
        it.x1 += dx; it.y1 += dy; it.x2 += dx; it.y2 += dy
    else:
        it.cx += dx; it.cy += dy

def item_rotate(it, px, py, deg) -> None:
    if isinstance(it, BoundaryItem):
        for i in range(0, len(it.pts), 2):
            it.pts[i], it.pts[i + 1] = rot_point(it.pts[i], it.pts[i + 1], px, py, deg)
    elif isinstance(it, LineItem):
        it.x1, it.y1 = rot_point(it.x1, it.y1, px, py, deg)
        it.x2, it.y2 = rot_point(it.x2, it.y2, px, py, deg)
    elif isinstance(it, RectItem):
        cx, cy = item_center(it)
        ncx, ncy = rot_point(cx, cy, px, py, deg)
        item_translate(it, ncx - cx, ncy - cy)
        it.rotation += deg
    elif isinstance(it, TextItem):
        cx, cy = item_center(it)
        ncx, ncy = rot_point(cx, cy, px, py, deg)
        new_rot = getattr(it, "rotation", 0.0) + deg
        ox, oy = _text_anchor_to_center_offset(it)
        rx, ry = rot_point(ox, oy, 0.0, 0.0, new_rot)
        it.x = ncx - rx
        it.y = ncy - ry
        it.rotation = new_rot
    elif isinstance(it, CircleItem):
        it.cx, it.cy = rot_point(it.cx, it.cy, px, py, deg)
    elif isinstance(it, ArcItem):
        it.cx, it.cy = rot_point(it.cx, it.cy, px, py, deg)
        it.a_start = (it.a_start + deg) % 360.0
        it.a_end = (it.a_end + deg) % 360.0
    elif isinstance(it, PolyItem):
        it.cx, it.cy = rot_point(it.cx, it.cy, px, py, deg)
        it.rotation += deg

def item_segments(it) -> List[Tuple[float, float, float, float]]:
    if isinstance(it, BoundaryItem):
        return list(boundary_edges(it))
    if isinstance(it, LineItem):
        return [(it.x1, it.y1, it.x2, it.y2)]
    if isinstance(it, RectItem):
        pts = rect_corners(it)
        out = []
        for i in range(4):
            a = i * 2
            b = ((i + 1) % 4) * 2
            out.append((pts[a], pts[a + 1], pts[b], pts[b + 1]))
        return out
    if isinstance(it, PolyItem):
        pts = poly_points(it)
        n = len(pts) // 2
        out = []
        for i in range(n):
            a = i * 2
            b = ((i + 1) % n) * 2
            out.append((pts[a], pts[a + 1], pts[b], pts[b + 1]))
        return out
    return []

def item_snap_points(it) -> List[Tuple[str, float, float]]:
    out: List[Tuple[str, float, float]] = []
    if isinstance(it, BoundaryItem):
        for i in range(0, len(it.pts), 2):
            out.append(("end", it.pts[i], it.pts[i + 1]))
        for x1, y1, x2, y2 in boundary_edges(it):
            out.append(("mid", (x1 + x2) * 0.5, (y1 + y2) * 0.5))
        return out
    if isinstance(it, LineItem):
        return [
            ("end", it.x1, it.y1),
            ("end", it.x2, it.y2),
            ("mid", (it.x1 + it.x2) * 0.5, (it.y1 + it.y2) * 0.5),
        ]
    if isinstance(it, CircleItem):
        return [
            ("center", it.cx, it.cy),
            ("quad", it.cx + it.r, it.cy),
            ("quad", it.cx - it.r, it.cy),
            ("quad", it.cx, it.cy + it.r),
            ("quad", it.cx, it.cy - it.r),
        ]
    if isinstance(it, ArcItem):
        s = math.radians(it.a_start)
        e = math.radians(it.a_end)
        m = math.radians((it.a_start + ((it.a_end - it.a_start) % 360.0) * 0.5) % 360.0)
        return [
            ("center", it.cx, it.cy),
            ("end", it.cx + it.r * math.cos(s), it.cy + it.r * math.sin(s)),
            ("end", it.cx + it.r * math.cos(e), it.cy + it.r * math.sin(e)),
            ("mid", it.cx + it.r * math.cos(m), it.cy + it.r * math.sin(m)),
        ]
    if isinstance(it, RectItem):
        p = rect_corners(it)
        out = [("end", p[i], p[i + 1]) for i in range(0, 8, 2)]
        out.append(("center", *item_center(it)))
        return out
    if isinstance(it, PolyItem):
        p = poly_points(it)
        out = [("end", p[i], p[i + 1]) for i in range(0, len(p), 2)]
        out.append(("center", it.cx, it.cy))
        return out
    if isinstance(it, TextItem):
        out.append(("center", *item_center(it)))
        return out
    return out

def item_hit(it, x, y, tol=PICK_RADIUS) -> bool:
    if isinstance(it, BoundaryItem):
        for x1, y1, x2, y2 in boundary_edges(it):
            if seg_distance(x, y, x1, y1, x2, y2) < tol:
                return True
        return False
    if isinstance(it, LineItem):
        return seg_distance(x, y, it.x1, it.y1, it.x2, it.y2) < tol
    if isinstance(it, CircleItem):
        return abs(dist(x, y, it.cx, it.cy) - it.r) < tol
    if isinstance(it, ArcItem):
        if abs(dist(x, y, it.cx, it.cy) - it.r) >= tol:
            return False
        return angle_in_ccw(ang(it.cx, it.cy, x, y), it.a_start, it.a_end)
    if isinstance(it, RectItem):
        for x1, y1, x2, y2 in item_segments(it):
            if seg_distance(x, y, x1, y1, x2, y2) < tol:
                return True
        return False
    if isinstance(it, PolyItem):
        for x1, y1, x2, y2 in item_segments(it):
            if seg_distance(x, y, x1, y1, x2, y2) < tol:
                return True
        return False
    if isinstance(it, TextItem):
        cx, cy = item_center(it)
        rx, ry = rot_point(x, y, cx, cy, -getattr(it, "rotation", 0.0))
        hw = max(1.0, float(it.text_w)) * 0.5
        hh = max(1.0, float(it.text_h)) * 0.5
        return (cx - hw - tol) <= rx <= (cx + hw + tol) and (cy - hh - tol) <= ry <= (cy + hh + tol)
    return False

class Tool(Enum):
    SELECT = auto(); MOVE = auto(); COPY = auto(); ROTATE = auto(); DELETE = auto()
    LINE = auto(); CHAIN = auto(); BOUNDARY = auto(); LINE_LA = auto()
    CIRCLE_CR = auto(); CIRCLE_R = auto(); CIRCLE_2P = auto(); ARC_3P = auto()
    RECT = auto(); POLY = auto()
    MEASURE = auto()

