def palette_color_by_name(name: str):
    for nm, rgba in COLOR_PALETTE:
        if nm.lower() == str(name).lower():
            return rgba
    return COLOR_PALETTE[0][1]

UI_ICON  = dp(34)
UI_COLS  = 2
