# ===== Widgets =====
class TextButton(ButtonBehavior, Label):
    bg = ListProperty(BTN_NEUTRAL)

    def __init__(self, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", dp(34))
        kw.setdefault("font_size", "12sp")
        super().__init__(**kw)
        self.color = TEXT_MAIN
        self.bold = True
        self.halign = "center"
        self.valign = "middle"
        with self.canvas.before:
            self._c = Color(*self.bg)
            self._r = RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(8)])
        self.bind(pos=self._up, size=self._up, bg=self._recolor)

    def _up(self, *a):
        self._r.pos, self._r.size = self.pos, self.size
        self.text_size = self.size

    def _recolor(self, *a):
        self._c.rgba = self.bg

class IconButton(ButtonBehavior, Widget):
    bg = ListProperty(BTN_IDLE)

    def __init__(self, name, drawer, callback=None, bg=BTN_IDLE, **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("size", (UI_ICON, UI_ICON))
        super().__init__(**kw)
        self.name = name
        self.drawer = drawer
        self.idle_bg = list(bg)
        self.bg = list(bg)

        with self.canvas.before:
            self._c = Color(*self.bg)
            self._r = RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(6)])
        self.bind(pos=self._sync, size=self._sync, bg=self._recolor)

        if callback:
            self.bind(on_release=lambda *_: callback())
        self._sync()

    def _sync(self, *a):
        self._r.pos, self._r.size = self.pos, self.size
        self.canvas.after.clear()
        side = min(self.width, self.height) * 0.70
        if side < 2:
            return
        try:
            self.drawer(self.canvas.after, self.center_x - side / 2.0,
                        self.center_y - side / 2.0, side, TEXT_MAIN)
        except Exception:
            log_error("icon draw")

    def _recolor(self, *a):
        self._c.rgba = self.bg

    def set_active(self, on: bool):
        self.bg = list(BTN_ACTIVE if on else self.idle_bg)

class ColorButton(ButtonBehavior, Widget):
    def __init__(self, color_name, color_value, callback=None, **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("size", (UI_ICON, UI_ICON))
        super().__init__(**kw)
        self.color_name = color_name
        self.color_value = color_value
        self.is_active = False

        with self.canvas.before:
            self._bg = Color(*BTN_IDLE)
            self._bg_rect = RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(6)])

        with self.canvas:
            self._col = Color(*color_value)
            self._col_rect = RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(4)])

        self.bind(pos=self._update, size=self._update)
        if callback:
            self.bind(on_release=lambda *_: callback(color_value))
        self._update()

    def _update(self, *a):
        pad = dp(3) if not self.is_active else 0
        self._bg_rect.pos = self.pos
        self._bg_rect.size = self.size
        self._col_rect.pos = (self.x + pad, self.y + pad)
        self._col_rect.size = (self.width - 2 * pad, self.height - 2 * pad)

    def set_active(self, on: bool):
        self.is_active = on
        self._bg.rgba = BTN_ACTIVE if on else BTN_IDLE
        self._update()

class SectionLabel(Label):
    def __init__(self, text, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", dp(14))
        super().__init__(text=text, font_size="8sp", bold=True, color=(0.42, 0.55, 0.68, 1), **kw)

# ===== Drawing Canvas =====
class DrawingCanvas(Widget):
    status_text = StringProperty("Ready")
    ortho = BooleanProperty(False)
    snap_enabled = BooleanProperty(True)
    snap_readout = StringProperty("HOVER: FREE")
    zoom_level = NumericProperty(1.0)
    current_color = ListProperty([1.0, 1.0, 1.0, 1.0])
    label_mode = NumericProperty(2)

    def __init__(self, **kw):
        super().__init__(**kw)
        self.items: List[BaseItem] = []
        self.undo_stack: List[tuple] = []
        self.redo_stack: List[tuple] = []
        self.selected: List[BaseItem] = []
        self.tool = Tool.SELECT
        self.poly_sides = 6

        self.pan_x = 0.0
        self.pan_y = 0.0
        self._panning = False
        self._pan_start = None

        self.utm_zone = 39
        self.utm_hemisphere = 'N'
        self.cell_dir = os.path.join(os.path.expanduser("~"), "pystation_cells")
        self.shared_py_dir = resolve_user_py_dir()
        self.drawing_dir = self.shared_py_dir
        self.export_dir = self.shared_py_dir
        self.current_doc_path = ""
        self.layers: Dict[str, dict] = {}
        self.active_layer = "Default"
        self.layer_selected_name = "Default"

        self._p1: Optional[Tuple[float, float]] = None
        self._p2: Optional[Tuple[float, float]] = None
        self._bpts: List[float] = []
        self._drag_item = None
        self._drag_before = None
        self._drag_last = None
        self._drag_ref_ang = 0.0
        self._drag_moved = False

        self._pending_cell_records: Optional[List[dict]] = None
        self._pending_cell_name = ""
        self._pending_text_spec: Optional[dict] = None
        self._snap_world: Optional[Tuple[float, float]] = None
        self._snap_kind = "free"
        self._snap_info = ""
        self._touches: Dict[object, object] = {}
        self._pinch_mode = False
        self._pinch_dist0 = 0.0
        self._pinch_zoom0 = 1.0
        self._pinch_anchor: Optional[Tuple[float, float]] = None
        self._pinch_mid0 = (0.0, 0.0)
        self.snap_modes = {
            "end": True,
            "mid": True,
            "int": True,
            "near": True,
            "center": True,
            "quad": True,
            "close": True,
        }
        self._tex_cache: Dict[Tuple, object] = {}

        self.bind(pos=self._redraw, size=self._redraw, label_mode=self._redraw)
        self._init_layers()
        self._update_snap_readout()

    # ----- text textures for canvas labels -----
    def _text_texture(self, text, font_size, color, bold=False, font_ref=None):
        shown = display_text(text)
        chosen_font, chosen_bold = resolve_font_name(font_ref or APP_FONT, bold)
        key = (shown, font_size, color, chosen_bold, chosen_font)
        tex = self._tex_cache.get(key)
        if tex is None:
            if len(self._tex_cache) > 400:
                self._tex_cache.clear()
            try:
                cl = CoreLabel(text=shown, font_name=chosen_font, font_size=font_size, bold=chosen_bold, color=color)
                cl.refresh()
                tex = cl.texture
            except Exception:
                log_error("label texture")
                return None
            self._tex_cache[key] = tex
        return tex

    def show_coord_info(self, x, y):
        try:
            lat, lon = UTMConverter.utm_to_lat_lon(x, y, self.utm_zone, self.utm_hemisphere)
            self.status_text = f"UTM: E={x:.2f} N={y:.2f} | Geo: {lat:.6f} deg {lon:.6f} deg"
        except Exception:
            self.status_text = f"UTM: E={x:.2f} N={y:.2f}"

    def to_canvas_coords(self, screen_x, screen_y) -> Tuple[float, float]:
        cx = (screen_x - self.center_x - self.pan_x) / self.zoom_level + self.center_x
        cy = (screen_y - self.center_y - self.pan_y) / self.zoom_level + self.center_y
        return cx, cy

    def to_screen_coords(self, canvas_x, canvas_y) -> Tuple[float, float]:
        sx = (canvas_x - self.center_x) * self.zoom_level + self.center_x + self.pan_x
        sy = (canvas_y - self.center_y) * self.zoom_level + self.center_y + self.pan_y
        return sx, sy

    def _ensure_cell_dir(self):
        os.makedirs(self.cell_dir, exist_ok=True)
        return self.cell_dir

    def _ensure_drawing_dir(self):
        self.drawing_dir = resolve_user_py_dir()
        os.makedirs(self.drawing_dir, exist_ok=True)
        return self.drawing_dir

    def _ensure_export_dir(self):
        self.export_dir = resolve_user_py_dir()
        os.makedirs(self.export_dir, exist_ok=True)
        return self.export_dir

    def _sanitize_doc_name(self, name: str) -> str:
        cleaned = "".join(ch if (ch.isalnum() or ch in ('-', '_')) else '_' for ch in str(name or '').strip())
        cleaned = cleaned.strip('_')
        return cleaned or "drawing"

    def _doc_display_name(self, path: str = "") -> str:
        src = path or self.current_doc_path
        if not src:
            return "Untitled"
        return os.path.splitext(os.path.basename(src))[0]

    def _py_dir_label(self) -> str:
        return self._ensure_drawing_dir()

    def _next_available_doc_name(self, prefix: str = "drawing") -> str:
        folder = self._ensure_drawing_dir()
        for i in range(1, 1000):
            name = f"{prefix}_{i:02d}"
            path = os.path.join(folder, f"{name}{DRAWING_EXT}")
            if not os.path.exists(path):
                return name
        return f"{prefix}_{int(math.floor(len(self.items) + 1)):02d}"

    def _sanitize_cell_name(self, name: str) -> str:
        cleaned = "".join(ch if (ch.isalnum() or ch in ('-', '_')) else '_' for ch in str(name or '').strip())
        cleaned = cleaned.strip('_')
        return cleaned or "cell"

    def _init_layers(self):
        self.layers = {}
        self._ensure_layer("Default", self.current_color, visible=True, locked=False)
        self.active_layer = "Default"
        self.layer_selected_name = "Default"
        self._sync_current_color_from_active_layer()

    def _norm_rgba(self, color) -> Tuple[float, float, float, float]:
        vals = list(color) if isinstance(color, (list, tuple)) else list(self.current_color)
        while len(vals) < 4:
            vals.append(1.0)
        return tuple(float(v) for v in vals[:4])

    def _layer_color_name(self, color) -> str:
        rgba = self._norm_rgba(color)
        best_name = "Default"
        best_score = None
        for nm, ref in COLOR_PALETTE:
            sc = sum(abs(rgba[i] - float(ref[i])) for i in range(4))
            if best_score is None or sc < best_score:
                best_name = nm
                best_score = sc
        return best_name

    def _color_layer_name(self, color) -> str:
        return self._layer_color_name(color)

    def _ensure_layer(self, name: str, color=None, visible: bool = True, locked: bool = False) -> dict:
        name = str(name or "Default").strip() or "Default"
        info = self.layers.get(name)
        if info is None:
            info = {
                "visible": bool(visible),
                "locked": bool(locked),
                "color": list(self._norm_rgba(color if color is not None else self.current_color)),
            }
            self.layers[name] = info
        else:
            info.setdefault("visible", True)
            info.setdefault("locked", False)
            info["color"] = list(self._norm_rgba(info.get("color", color if color is not None else self.current_color)))
        return info

    def _ensure_item_layer(self, it):
        name = str(getattr(it, "layer_name", "") or "").strip()
        if not name:
            name = self._color_layer_name(getattr(it, "color", self.current_color))
        info = self._ensure_layer(name, getattr(it, "color", self.current_color))
        it.layer_name = name
        if not getattr(it, "color", None):
            it.color = tuple(info["color"])
        return name

    def _assign_items_to_layers_by_color(self, items=None, force_by_color: bool = False):
        target = self.items if items is None else items
        for it in target:
            name = str(getattr(it, "layer_name", "") or "").strip()
            if force_by_color or not name:
                name = self._color_layer_name(getattr(it, "color", self.current_color))
            info = self._ensure_layer(name, getattr(it, "color", self.current_color))
            it.layer_name = name
            if len(getattr(it, "color", ())) < 4:
                it.color = tuple(info["color"])
        if self.active_layer not in self.layers:
            self.active_layer = next(iter(self.layers.keys()), "Default")
        self.layer_selected_name = self.active_layer
        self._sync_current_color_from_active_layer()

    def _layer_visible(self, name: str) -> bool:
        return bool(self._ensure_layer(name).get("visible", True))

    def _layer_locked(self, name: str) -> bool:
        return bool(self._ensure_layer(name).get("locked", False))

    def _item_layer_visible(self, it) -> bool:
        return self._layer_visible(self._ensure_item_layer(it))

    def _item_layer_locked(self, it) -> bool:
        return self._layer_locked(self._ensure_item_layer(it))

    def _sync_current_color_from_active_layer(self):
        info = self._ensure_layer(self.active_layer)
        self.current_color = list(self._norm_rgba(info.get("color", self.current_color)))

    def layer_names(self) -> List[str]:
        self._assign_items_to_layers_by_color()
        return list(self.layers.keys())

    def layer_item_count(self, name: str) -> int:
        return sum(1 for it in self.items if self._ensure_item_layer(it) == name)

    def create_layer(self, name: str, color=None) -> Tuple[bool, str]:
        name = str(name or "").strip()
        if not name:
            return False, "Layer name required"
        if name in self.layers:
            return False, f"Layer exists: {name}"
        self._ensure_layer(name, color if color is not None else self.current_color)
        self.layer_selected_name = name
        self.status_text = f"Layer created: {name}"
        self._redraw()
        return True, name

    def set_active_layer(self, name: str) -> Tuple[bool, str]:
        name = str(name or "").strip()
        if not name:
            return False, "Layer name required"
        if name not in self.layers:
            return False, f"Layer not found: {name}"
        if self._layer_locked(name):
            return False, f"Layer locked: {name}"
        if not self._layer_visible(name):
            return False, f"Layer hidden: {name}"
        self.active_layer = name
        self.layer_selected_name = name
        self._sync_current_color_from_active_layer()
        self.status_text = f"Current layer: {name}"
        self._redraw()
        return True, name

    def toggle_layer_visible(self, name: str) -> Tuple[bool, str]:
        name = str(name or "").strip()
        if name not in self.layers:
            return False, f"Layer not found: {name}"
        if name == self.active_layer and self._layer_visible(name):
            return False, "Cannot hide current layer"
        info = self.layers[name]
        info["visible"] = not bool(info.get("visible", True))
        self.status_text = f"Layer {name}: {'ON' if info['visible'] else 'OFF'}"
        self.selected = [it for it in self.selected if self._item_layer_visible(it)]
        self._redraw()
        return True, name

    def toggle_layer_locked(self, name: str) -> Tuple[bool, str]:
        name = str(name or "").strip()
        if name not in self.layers:
            return False, f"Layer not found: {name}"
        if name == self.active_layer and not self._layer_locked(name):
            return False, "Cannot lock current layer"
        info = self.layers[name]
        info["locked"] = not bool(info.get("locked", False))
        self.status_text = f"Layer {name}: {'LOCK' if info['locked'] else 'UNLOCK'}"
        self._redraw()
        return True, name

    def set_layer_color(self, name: str, color) -> Tuple[bool, str]:
        name = str(name or "").strip()
        if name not in self.layers:
            return False, f"Layer not found: {name}"
        info = self.layers[name]
        rgba = list(self._norm_rgba(color))
        info["color"] = rgba
        for it in self.items:
            if self._ensure_item_layer(it) == name:
                it.color = tuple(rgba)
        if name == self.active_layer:
            self.current_color = list(rgba)
        self.status_text = f"Layer color: {name}"
        self._redraw()
        return True, name

    def move_selected_to_layer(self, name: str) -> Tuple[bool, str]:
        name = str(name or "").strip()
        if not self.selected:
            return False, "No selected items"
        if name not in self.layers:
            return False, f"Layer not found: {name}"
        if self._layer_locked(name):
            return False, f"Target layer locked: {name}"
        moved = 0
        skipped = 0
        target_col = tuple(self.layers[name]["color"])
        for it in self.selected:
            if self._item_layer_locked(it):
                skipped += 1
                continue
            it.layer_name = name
            it.color = target_col
            moved += 1
        self.status_text = f"Moved to {name}: {moved} | locked skip: {skipped}"
        self._redraw()
        return True, name

    def _can_draw_on_active_layer(self) -> bool:
        self._ensure_layer(self.active_layer)
        if self._layer_locked(self.active_layer):
            self.status_text = f"Current layer locked: {self.active_layer}"
            return False
        if not self._layer_visible(self.active_layer):
            self.status_text = f"Current layer hidden: {self.active_layer}"
            return False
        return True

    def _tool_prompt(self, tool: Optional[Tool] = None) -> str:
        tool = self.tool if tool is None else tool
        prompts = {
            Tool.SELECT: "Select - tap items",
            Tool.MOVE: "Move - tap item then drag",
            Tool.COPY: "Copy - tap item then drag",
            Tool.ROTATE: "Rotate - tap item then drag",
            Tool.DELETE: "Delete - tap item",
            Tool.LINE: "Line - smart snap ON - tap start point",
            Tool.CHAIN: "Polyline - smart snap ON - tap first point",
            Tool.BOUNDARY: "Boundary - smart snap ON - tap first vertex",
            Tool.LINE_LA: "Length/Angle - tap start point, then open Key-in",
            Tool.CIRCLE_CR: "Circle CR - tap center",
            Tool.CIRCLE_R: "Circle R - tap center then enter radius",
            Tool.CIRCLE_2P: "Circle 2P - tap first point",
            Tool.ARC_3P: "Arc 3P - tap first point",
            Tool.RECT: "Rectangle - tap first corner",
            Tool.POLY: "Polygon - tap center",
            Tool.MEASURE: "Measure - tap first point",
        }
        return prompts.get(tool, f"{tool.name.title()} - tap on canvas")

    def zoom_in(self):
        self.zoom_level = min(self.zoom_level * 1.3, 20.0)
        self.status_text = f"Zoom: {self.zoom_level:.1f}x"
        self._redraw()

    def zoom_out(self):
        self.zoom_level = max(self.zoom_level / 1.3, 0.1)
        self.status_text = f"Zoom: {self.zoom_level:.1f}x"
        self._redraw()

    def zoom_fit(self):
        if not self.items:
            self.zoom_level = 1.0
            self.pan_x = 0.0
            self.pan_y = 0.0
            self.status_text = "No items to fit"
            self._redraw()
            return

        min_x = min_y = float('inf')
        max_x = max_y = float('-inf')
        for it in self.items:
            x1, y1, x2, y2 = item_bounds(it)
            min_x = min(min_x, x1)
            min_y = min(min_y, y1)
            max_x = max(max_x, x2)
            max_y = max(max_y, y2)

        margin = 50
        min_x -= margin
        min_y -= margin
        max_x += margin
        max_y += margin
        width = max_x - min_x
        height = max_y - min_y
        if width <= 0 or height <= 0:
            return

        zoom_x = self.width / width
        zoom_y = self.height / height
        self.zoom_level = min(zoom_x, zoom_y, 10.0)

        cx = (min_x + max_x) / 2
        cy = (min_y + max_y) / 2
        self.pan_x = (self.center_x - cx) * self.zoom_level
        self.pan_y = (self.center_y - cy) * self.zoom_level

        self.status_text = f"Fit view - Zoom: {self.zoom_level:.1f}x"
        self._redraw()

    def set_tool(self, tool: Tool):
        self.tool = tool
        self.cancel_pending_cell()
        self.cancel_pending_text()
        self._reset_pending(keep_cell=False)
        self._snap_info = self._active_snap_modes_text() if self.snap_enabled else "OFF"
        self.status_text = f"{self._tool_prompt(tool)} | SNAP={self._snap_info}"

    def toggle_ortho(self):
        self.ortho = not self.ortho
        self.status_text = f"Ortho {'ON' if self.ortho else 'OFF'}"

    def _screen_aperture(self) -> float:
        if self.tool in (Tool.LINE, Tool.CHAIN, Tool.BOUNDARY, Tool.LINE_LA):
            return 72.0
        if self.tool in (Tool.CIRCLE_CR, Tool.CIRCLE_R, Tool.CIRCLE_2P, Tool.ARC_3P, Tool.RECT, Tool.POLY):
            return 54.0
        return 44.0

    def _snap_world_tol(self, px_radius: Optional[float] = None) -> float:
        px = self._screen_aperture() if px_radius is None else float(px_radius)
        return px / max(self.zoom_level, 0.1)

    def _min_geom_tol(self) -> float:
        return max(0.25, self._snap_world_tol(6.0))

    def _snap_capture_px(self, kind: str, base_px: float) -> float:
        if kind == "close":
            return base_px * 2.10
        if kind == "end":
            return base_px * 1.85
        if kind == "int":
            return base_px * 1.35
        if kind == "mid":
            return base_px * 1.10
        if kind in ("center", "quad"):
            return base_px * 1.15
        if kind == "near":
            return base_px * 0.58
        return base_px

    def _draft_snap_points(self) -> List[Tuple[str, float, float]]:
        out: List[Tuple[str, float, float]] = []
        if self._p1 is not None and self.tool in (Tool.LINE, Tool.CHAIN, Tool.BOUNDARY, Tool.LINE_LA, Tool.MEASURE):
            out.append(("end", self._p1[0], self._p1[1]))
        if self._p2 is not None and self.tool == Tool.ARC_3P:
            out.append(("end", self._p2[0], self._p2[1]))
        if self._bpts:
            n = len(self._bpts) // 2
            for i in range(n):
                kind = "close" if (self.tool == Tool.BOUNDARY and i == 0 and n >= 3) else "end"
                out.append((kind, self._bpts[2 * i], self._bpts[2 * i + 1]))
            for i in range(n - 1):
                x1, y1 = self._bpts[2 * i], self._bpts[2 * i + 1]
                x2, y2 = self._bpts[2 * i + 2], self._bpts[2 * i + 3]
                out.append(("mid", (x1 + x2) * 0.5, (y1 + y2) * 0.5))
        return out

    def _draft_segments(self) -> List[Tuple[float, float, float, float]]:
        segs: List[Tuple[float, float, float, float]] = []
        if len(self._bpts) >= 4:
            for i in range(0, len(self._bpts) - 2, 2):
                segs.append((self._bpts[i], self._bpts[i + 1], self._bpts[i + 2], self._bpts[i + 3]))
        if self.tool == Tool.ARC_3P and self._p1 is not None and self._p2 is not None:
            segs.append((self._p1[0], self._p1[1], self._p2[0], self._p2[1]))
        return segs

    def _snap_mode_enabled(self, kind: str) -> bool:
        if kind == "close":
            return bool(self.snap_modes.get("close", True) and self.snap_modes.get("end", True))
        return bool(self.snap_modes.get(kind, True))

    def _active_snap_modes_text(self) -> str:
        order = [("end", "END"), ("mid", "MID"), ("int", "INT"),
                 ("near", "NEAR"), ("center", "CENTER"),
                 ("quad", "QUAD"), ("close", "CLOSE")]
        active = [title for kind, title in order if self._snap_mode_enabled(kind)]
        return " ".join(active) if active else "NONE"

    def _update_snap_readout(self, hover_kind: Optional[str] = None):
        if not self.snap_enabled:
            self.snap_readout = "HOVER: OFF | MODES: OFF"
            return
        title = self._snap_kind_title(hover_kind) if hover_kind else self._snap_kind_title()
        self.snap_readout = f"HOVER: {title} | MODES: {self._active_snap_modes_text()}"

    def _reset_snap_visuals(self):
        self._snap_world = None
        self._snap_kind = "free"
        self.canvas.after.clear()
        self._update_snap_readout()
        self._redraw()

    def set_snap_enabled(self, enabled: bool):
        self.snap_enabled = bool(enabled)
        self._snap_info = self._active_snap_modes_text() if self.snap_enabled else "OFF"
        self._reset_snap_visuals()
        self.status_text = f"Snap {'ON' if self.snap_enabled else 'OFF'}"

    def set_snap_mode(self, kind: str, enabled: bool):
        if kind not in self.snap_modes:
            return False
        self.snap_modes[kind] = bool(enabled)
        self._snap_info = self._active_snap_modes_text() if self.snap_enabled else "OFF"
        self._reset_snap_visuals()
        state = "ON" if self.snap_modes[kind] else "OFF"
        self.status_text = f"Snap {kind.upper()} {state}"
        return True

    def toggle_snap(self):
        self.set_snap_enabled(not self.snap_enabled)

    def toggle_snap_mode(self, kind: str):
        if kind not in self.snap_modes:
            return
        self.set_snap_mode(kind, not self.snap_modes[kind])

    def _apply_ortho_after_snap(self, x1, y1, x, y):
        if self.snap_enabled and self._snap_kind in ("close", "end", "int", "mid", "center", "quad"):
            return x, y
        return self._ortho(x1, y1, x, y)

    def _touch_midpoint(self) -> Optional[Tuple[float, float]]:
        if len(self._touches) < 2:
            return None
        pts = list(self._touches.values())[:2]
        return ((pts[0].x + pts[1].x) * 0.5, (pts[0].y + pts[1].y) * 0.5)

    def _touch_distance(self) -> float:
        if len(self._touches) < 2:
            return 0.0
        pts = list(self._touches.values())[:2]
        return dist(pts[0].x, pts[0].y, pts[1].x, pts[1].y)

    def _begin_pinch(self):
        if len(self._touches) < 2:
            return
        mid = self._touch_midpoint()
        if mid is None:
            return
        self._pinch_mode = True
        self._panning = False
        self._pinch_mid0 = mid
        self._pinch_dist0 = max(10.0, self._touch_distance())
        self._pinch_zoom0 = self.zoom_level
        self._pinch_anchor = self.to_canvas_coords(*mid)
        self.canvas.after.clear()
        self._snap_world = None
        self._snap_kind = "free"
        self._snap_info = "PINCH"
        self._update_snap_readout("free")
        self.status_text = "Pinch zoom / pan"

    def _update_pinch(self):
        if not self._pinch_mode or len(self._touches) < 2 or self._pinch_anchor is None:
            return
        mid = self._touch_midpoint()
        if mid is None:
            return
        d_now = max(10.0, self._touch_distance())
        scale = d_now / max(10.0, self._pinch_dist0)
        self.zoom_level = clamp(self._pinch_zoom0 * scale, 0.1, 30.0)
        ax, ay = self._pinch_anchor
        self.pan_x = mid[0] - self.center_x - (ax - self.center_x) * self.zoom_level
        self.pan_y = mid[1] - self.center_y - (ay - self.center_y) * self.zoom_level
        self.status_text = f"Pinch zoom: {self.zoom_level:.2f}x"
        self._redraw()

    def _end_pinch(self):
        self._pinch_mode = False
        self._pinch_anchor = None
        self._pinch_dist0 = 0.0
        self._snap_info = ""
        self._update_snap_readout()
        self.status_text = f"Zoom: {self.zoom_level:.2f}x"

    def finish(self):
        if self._pending_text_spec:
            self.cancel_pending_text()
            self.status_text = "Text insert cancelled"
            self._redraw()
            return
        if self._pending_cell_records:
            self.cancel_pending_cell()
            return
        if self.tool in (Tool.BOUNDARY, Tool.CHAIN) and self._bpts:
            n = len(self._bpts) // 2
            need = 3 if self.tool == Tool.BOUNDARY else 2
            if n >= need:
                item = BoundaryItem(pts=list(self._bpts), closed=(self.tool == Tool.BOUNDARY))
                self._add(item)
                if item.closed:
                    self.status_text = f"Boundary closed: {n} vertices, area {boundary_area(item):,.1f} m2"
                else:
                    self.status_text = f"Polyline finished: {n} vertices"
            else:
                self.status_text = f"Need at least {need} points"
        else:
            self.status_text = "Finished"
        self._reset_pending(keep_cell=False)

    def clear_all(self):
        if self.items:
            self._push(("clear", list(self.items)))
            self.items = []
        self.selected = []
        self._reset_pending(keep_cell=False)
        self.status_text = "Cleared (undoable)"

    def delete_selected(self):
        removed = 0
        locked = 0
        for it in list(self.selected):
            if self._item_layer_locked(it):
                locked += 1
                continue
            removed += 1 if self._remove(it) else 0
        self.selected = [it for it in self.selected if self._item_layer_locked(it)]
        self.status_text = f"Deleted {removed} item(s) | locked skip: {locked}"
        self._redraw()

    def set_drawing_color(self, color: Tuple[float, float, float, float]):
        self.current_color = list(color)
        self._ensure_layer(self.active_layer, color)
        self.layers[self.active_layer]["color"] = list(self._norm_rgba(color))
        self.status_text = f"Color set | Layer: {self.active_layer}"

    def _push(self, entry):
        self.undo_stack.append(entry)
        if len(self.undo_stack) > 200:
            self.undo_stack.pop(0)
        self.redo_stack = []

    def _add(self, item, preserve_style: bool = False, redraw: bool = True) -> BaseItem:
        if not preserve_style:
            if not self._can_draw_on_active_layer():
                return item
            item.color = tuple(self.current_color)
            item.layer_name = self.active_layer
        else:
            self._ensure_item_layer(item)
        self.items.append(item)
        self._push(("add", item, len(self.items) - 1))
        if redraw:
            self._redraw()
        return item

    def _add_group(self, items: List[BaseItem], preserve_style: bool = False):
        if not items:
            return []
        start_index = len(self.items)
        added: List[BaseItem] = []
        for it in items:
            if not preserve_style:
                if not self._can_draw_on_active_layer():
                    continue
                it.color = tuple(self.current_color)
                it.layer_name = self.active_layer
            else:
                self._ensure_item_layer(it)
            self.items.append(it)
            added.append(it)
        if added:
            self._push(("add_group", list(added), start_index))
        self._redraw()
        return added

    def _remove(self, item):
        for i, it in enumerate(self.items):
            if it is item:
                self.items.pop(i)
                self._push(("del", item, i))
                return True
        return False

    @staticmethod
    def _snap_state(it) -> dict:
        st = dict(it.__dict__)
        if 'pts' in st:
            st['pts'] = list(st['pts'])
        return st

    @staticmethod
    def _apply_state(it, state: dict):
        it.__dict__.update(state)

    def undo(self):
        if not self.undo_stack:
            self.status_text = "Nothing to undo"
            return
        e = self.undo_stack.pop()
        kind = e[0]
        if kind == "add":
            for i, it in enumerate(self.items):
                if it is e[1]:
                    self.items.pop(i)
                    break
        elif kind == "add_group":
            for it in reversed(e[1]):
                for i in range(len(self.items) - 1, -1, -1):
                    if self.items[i] is it:
                        self.items.pop(i)
                        break
        elif kind == "del":
            self.items.insert(min(e[2], len(self.items)), e[1])
        elif kind == "mod":
            self._apply_state(e[1], e[2])
        elif kind == "clear":
            self.items = list(e[1])
        self.redo_stack.append(e)
        self.selected = []
        self.status_text = "Undo"
        self._redraw()

    def redo(self):
        if not self.redo_stack:
            self.status_text = "Nothing to redo"
            return
        e = self.redo_stack.pop()
        kind = e[0]
        if kind == "add":
            self.items.insert(min(e[2], len(self.items)), e[1])
        elif kind == "add_group":
            idx = min(e[2], len(self.items))
            for off, it in enumerate(e[1]):
                self.items.insert(idx + off, it)
        elif kind == "del":
            for i, it in enumerate(self.items):
                if it is e[1]:
                    self.items.pop(i)
                    break
        elif kind == "mod":
            self._apply_state(e[1], e[3])
        elif kind == "clear":
            self.items = []
        self.undo_stack.append(e)
        self.selected = []
        self.status_text = "Redo"
        self._redraw()

    def select_all(self, visible_only: bool = True):
        if visible_only:
            self.selected = [it for it in self.items if self._item_layer_visible(it)]
        else:
            self.selected = list(self.items)
        self.status_text = f"Select All: {len(self.selected)} item(s)"
        self._redraw()

    def place_by_length_angle(self, length: float, angle: float):
        if self._p1 is None:
            self.status_text = "Pick a start point first (L/A tool)"
            return
        if length <= 0:
            self.status_text = "Length must be > 0"
            return
        x1, y1 = self._p1
        x2 = x1 + length * math.cos(math.radians(angle))
        y2 = y1 + length * math.sin(math.radians(angle))
        self._add(LineItem(x1=x1, y1=y1, x2=x2, y2=y2))
        self._p1 = (x2, y2)
        self.status_text = f"Line by key-in | L={length:.2f} | A={angle:.2f} deg"

    def place_circle_by_radius(self, radius: float):
        if self._p1 is None:
            self.status_text = "Pick circle center first"
            return
        if radius <= 0:
            self.status_text = "Radius must be > 0"
            return
        cx, cy = self._p1
        self._add(CircleItem(cx=cx, cy=cy, r=radius))
        self._p1 = None
        self.status_text = f"Circle R created | R={radius:.2f}"

    def available_text_fonts(self) -> List[Tuple[str, str]]:
        return list_available_font_choices()

    def begin_text_insert(self, text_value: str, font_ref: str, font_size: float, rotation: float = 0.0,
                          align: str = "right", bold: bool = False, color=None):
        if not self._can_draw_on_active_layer():
            return False
        message = repair_mojibake_text(str(text_value or "")).rstrip()
        if not message.strip():
            self.status_text = "Text is empty"
            return False
        try:
            size = float(font_size)
        except Exception:
            self.status_text = "Invalid text size"
            return False
        if size <= 0:
            self.status_text = "Text size must be > 0"
            return False
        try:
            rot = float(rotation)
        except Exception:
            rot = 0.0
        align_mode = str(align or "right").lower()
        if align_mode not in ("left", "center", "right"):
            align_mode = "right"
        text_color = tuple(self._norm_rgba(color if color is not None else self.current_color))
        self.cancel_pending_cell()
        self.cancel_pending_text()
        self._reset_pending(keep_cell=False)
        self._pending_text_spec = {
            "text": message,
            "font_ref": normalize_font_ref(font_ref),
            "font_size": size,
            "rotation": rot,
            "align": align_mode,
            "bold": bool(bold),
            "color": list(text_color),
        }
        preview = message.replace("\n", " ")[:28]
        self.status_text = f"Text insert ready: {preview} | tap insertion point"
        return True

    def cancel_pending_text(self):
        self._pending_text_spec = None

    def _preview_pending_text(self, x: float, y: float):
        spec = self._pending_text_spec
        if not spec:
            return
        tw, th = estimate_text_world_box(spec.get("text", ""), spec.get("font_size", 24.0))
        temp = TextItem(
            x=x, y=y,
            text=str(spec.get("text", "")),
            font_ref=str(spec.get("font_ref", APP_FONT)),
            font_size=float(spec.get("font_size", 24.0)),
            rotation=float(spec.get("rotation", 0.0)),
            text_w=tw,
            text_h=th,
            align=str(spec.get("align", "right")),
            bold=bool(spec.get("bold", False)),
            color=tuple(spec.get("color", self.current_color)),
            layer_name=self.active_layer,
        )
        self._draw_item_geometry(self.canvas.after, temp, color=temp.color, width=max(1.0, self.zoom_level))

    def _place_pending_text(self, x: float, y: float):
        spec = self._pending_text_spec
        if not spec:
            return False
        tw, th = estimate_text_world_box(spec.get("text", ""), spec.get("font_size", 24.0))
        item = TextItem(
            x=x, y=y,
            text=str(spec.get("text", "")),
            font_ref=str(spec.get("font_ref", APP_FONT)),
            font_size=float(spec.get("font_size", 24.0)),
            rotation=float(spec.get("rotation", 0.0)),
            text_w=tw,
            text_h=th,
            align=str(spec.get("align", "right")),
            bold=bool(spec.get("bold", False)),
            color=tuple(spec.get("color", self.current_color)),
            layer_name=self.active_layer,
        )
        self._pending_text_spec = None
        self._add(item, preserve_style=True, redraw=False)
        preview = item.text.replace("\n", " ")[:28]
        self.status_text = f"Text inserted: {preview}"
        self.canvas.after.clear()
        self._redraw()
        return True

    def _reset_pending(self, keep_cell: bool = True):
        self._p1 = self._p2 = None
        self._bpts = []
        self._drag_item = None
        self._drag_before = None
        self._drag_last = None
        self._drag_moved = False
        self._panning = False
        self.canvas.after.clear()
        self._snap_world = None
        self._snap_kind = "free"
        self._snap_info = ""
        self._update_snap_readout()
        if not keep_cell:
            self._pending_cell_records = None
            self._pending_cell_name = ""
        self._pending_text_spec = None
        self._redraw()

    def _ortho(self, x1, y1, x, y):
        if not self.ortho:
            return x, y
        return (x, y1) if abs(x - x1) >= abs(y - y1) else (x1, y)

    def _pick(self, x, y):
        tol = PICK_RADIUS / max(self.zoom_level, 0.1)
        for it in reversed(self.items):
            if not self._item_layer_visible(it):
                continue
            if item_hit(it, x, y, tol):
                return it
        return None

    def _is_sel(self, it) -> bool:
        return any(s is it for s in self.selected)

    def _snap_priority(self, kind: str) -> int:
        order = {
            "close": -1,
            "end": 0,
            "int": 1,
            "mid": 2,
            "center": 3,
            "quad": 4,
            "near": 6,
            "free": 9,
        }
        return order.get(kind, 8)

    def _snap_bias(self, kind: str) -> float:
        bias = {
            "close": -24.0,
            "end": -16.0,
            "int": -8.0,
            "mid": -1.0,
            "center": 1.0,
            "quad": 2.0,
            "near": 18.0,
            "free": 99.0,
        }.get(kind, 10.0)
        if self.tool in (Tool.LINE, Tool.CHAIN, Tool.BOUNDARY, Tool.LINE_LA):
            if kind in ("close", "end"):
                bias -= 10.0
            elif kind == "int":
                bias -= 4.0
            elif kind == "mid":
                bias -= 2.0
            elif kind == "near":
                bias += 8.0
        return bias

    def _snap_kind_title(self, kind: Optional[str] = None) -> str:
        kind = self._snap_kind if kind is None else kind
        titles = {
            "close": "CLOSE",
            "end": "END",
            "int": "INT",
            "mid": "MID",
            "center": "CENTER",
            "quad": "QUAD",
            "near": "NEAR",
            "free": "FREE",
        }
        return titles.get(kind, str(kind).upper())

    def _snap(self, x, y, screen: Optional[Tuple[float, float]] = None) -> Tuple[float, float]:
        screen_x, screen_y = screen if screen is not None else self.to_screen_coords(x, y)

        if not self.snap_enabled:
            self._snap_world = (x, y)
            self._snap_kind = "free"
            self._snap_info = "OFF"
            self._update_snap_readout("free")
            return x, y

        snap_px = self._screen_aperture()
        stick_px = max(SNAP_STICK_RADIUS, snap_px + 12.0)
        near_world = self._snap_world_tol(snap_px)
        best = None
        near_segments = []

        if self._snap_world is not None and self._snap_kind != "free":
            ssx, ssy = self.to_screen_coords(*self._snap_world)
            if dist(screen_x, screen_y, ssx, ssy) <= stick_px:
                self._snap_info = self._snap_kind_title()
                self._update_snap_readout(self._snap_kind)
                return self._snap_world

        def add_candidate(px, py, kind):
            nonlocal best
            if not self._snap_mode_enabled(kind):
                return
            ssx, ssy = self.to_screen_coords(px, py)
            sd = dist(screen_x, screen_y, ssx, ssy)
            cap = self._snap_capture_px(kind, snap_px)
            if sd > cap:
                return
            hard = 0.0
            if kind in ("close", "end") and sd <= min(cap, SNAP_END_HARDLOCK_PX):
                hard = -100.0
            elif kind == "int" and sd <= min(cap, SNAP_INT_HARDLOCK_PX):
                hard = -70.0
            score = (hard, self._snap_priority(kind), sd + self._snap_bias(kind), sd)
            if best is None or score < best[0]:
                best = (score, (px, py, kind))

        for kind, px, py in self._draft_snap_points():
            add_candidate(px, py, kind)

        for seg in self._draft_segments():
            x1, y1, x2, y2 = seg
            qx, qy, t, wd = project_to_segment(x, y, x1, y1, x2, y2)
            if wd <= near_world * 1.35:
                near_segments.append((-1, seg))
                if 0.12 <= t <= 0.88:
                    add_candidate(qx, qy, "near")

        for idx, it in enumerate(self.items):
            if not self._item_layer_visible(it):
                continue
            for kind, px, py in item_snap_points(it):
                add_candidate(px, py, kind)
            for seg in item_segments(it):
                x1, y1, x2, y2 = seg
                qx, qy, t, wd = project_to_segment(x, y, x1, y1, x2, y2)
                if wd <= near_world * 1.35:
                    near_segments.append((idx, seg))
                    if 0.12 <= t <= 0.88:
                        add_candidate(qx, qy, "near")

        pair_limit = min(len(near_segments), 64)
        if self._snap_mode_enabled("int"):
            for i in range(pair_limit):
                idx1, s1 = near_segments[i]
                for j in range(i + 1, pair_limit):
                    idx2, s2 = near_segments[j]
                    if idx1 == idx2 and idx1 >= 0:
                        continue
                    hit = seg_intersection(*s1, *s2)
                    if hit is None:
                        continue
                    add_candidate(hit[0], hit[1], "int")

        if best is None:
            self._snap_world = (x, y)
            self._snap_kind = "free"
            self._snap_info = "FREE"
            self._update_snap_readout("free")
            return x, y

        px, py, kind = best[1]
        self._snap_world = (px, py)
        self._snap_kind = kind
        self._snap_info = self._snap_kind_title(kind)
        self._update_snap_readout(kind)
        return px, py

    def _draw_snap_marker(self):
        if self._snap_world is None or self._snap_kind == "free":
            return
        sx, sy = self.to_screen_coords(*self._snap_world)
        kind = self._snap_kind
        color = SNAP_COLORS.get(kind, PREVIEW)
        r = dp(6.2)
        with self.canvas.after:
            Color(*color)
            if kind in ("end", "close"):
                Line(rectangle=(sx - r, sy - r, r * 2, r * 2), width=1.25)
                Line(points=[sx - r - 4, sy, sx + r + 4, sy], width=1.0)
                Line(points=[sx, sy - r - 4, sx, sy + r + 4], width=1.0)
            elif kind == "mid":
                Line(points=[sx, sy + r, sx + r, sy, sx, sy - r, sx - r, sy, sx, sy + r], width=1.25)
            elif kind == "int":
                Line(points=[sx - r, sy - r, sx + r, sy + r], width=1.25)
                Line(points=[sx - r, sy + r, sx + r, sy - r], width=1.25)
            elif kind == "center":
                Line(circle=(sx, sy, r), width=1.25)
                Line(points=[sx - r - 4, sy, sx + r + 4, sy], width=1.0)
                Line(points=[sx, sy - r - 4, sx, sy + r + 4], width=1.0)
            elif kind == "quad":
                Line(circle=(sx, sy, r * 0.85), width=1.05)
                Line(points=[sx - r - 3, sy, sx + r + 3, sy], width=1.0)
            else:
                Line(circle=(sx, sy, r * 0.85), width=1.05)
                Line(points=[sx - r, sy + r * 0.22, sx + r, sy - r * 0.22], width=1.0)

            tex = self._text_texture(self._snap_kind_title(kind), 10, color, True)
            if tex is not None and tex.width >= 1:
                tw, th = tex.size
                Color(*LBL_CHIP)
                Rectangle(pos=(sx + r + 6, sy + r + 4), size=(tw + 6, th + 4))
                Color(1, 1, 1, 1)
                Rectangle(texture=tex, pos=(sx + r + 9, sy + r + 6), size=(tw, th))

    def _preview_line(self, x1, y1, x2, y2):
        sx1, sy1 = self.to_screen_coords(x1, y1)
        sx2, sy2 = self.to_screen_coords(x2, y2)
        with self.canvas.after:
            Color(*PREVIEW)
            Line(points=[sx1, sy1, sx2, sy2], width=1.5, dash_length=6, dash_offset=4)
        self._draw_snap_marker()

    def _preview_circle(self, cx, cy, r):
        if r <= 0.5:
            self._draw_snap_marker()
            return
        scx, scy = self.to_screen_coords(cx, cy)
        sr = r * self.zoom_level
        with self.canvas.after:
            Color(*PREVIEW)
            Line(circle=(scx, scy, sr), width=1.5, dash_length=6, dash_offset=4)
        self._draw_snap_marker()

    def _preview_poly(self, pts, close=True):
        if len(pts) < 4:
            self._draw_snap_marker()
            return
        screen_pts = []
        for i in range(0, len(pts), 2):
            sx, sy = self.to_screen_coords(pts[i], pts[i + 1])
            screen_pts.extend([sx, sy])
        with self.canvas.after:
            Color(*PREVIEW)
            Line(points=screen_pts, width=1.5, dash_length=6, dash_offset=4, close=close)
        self._draw_snap_marker()

    def _draw_item_geometry(self, target_canvas, it, color=None, width=None, draw_vertex_rings=True):
        color = it.color if color is None else color
        width = it.width * self.zoom_level if width is None else width
        with target_canvas:
            Color(*color)
            if isinstance(it, BoundaryItem):
                if len(it.pts) >= 4:
                    screen_pts = []
                    for i in range(0, len(it.pts), 2):
                        sx, sy = self.to_screen_coords(it.pts[i], it.pts[i + 1])
                        screen_pts.extend([sx, sy])
                    Line(points=screen_pts, width=width, close=it.closed)
                if draw_vertex_rings:
                    Color(*LBL_VERTEX)
                    for i in range(0, len(it.pts), 2):
                        sx, sy = self.to_screen_coords(it.pts[i], it.pts[i + 1])
                        Line(circle=(sx, sy, dp(3.5)), width=1.3)
            elif isinstance(it, LineItem):
                sx1, sy1 = self.to_screen_coords(it.x1, it.y1)
                sx2, sy2 = self.to_screen_coords(it.x2, it.y2)
                Line(points=[sx1, sy1, sx2, sy2], width=width)
            elif isinstance(it, CircleItem):
                if it.r > 0.5:
                    scx, scy = self.to_screen_coords(it.cx, it.cy)
                    sr = it.r * self.zoom_level
                    Line(circle=(scx, scy, sr), width=width)
            elif isinstance(it, ArcItem):
                if it.r > 0.5:
                    scx, scy = self.to_screen_coords(it.cx, it.cy)
                    sr = it.r * self.zoom_level
                    a1, a2 = arc_kivy_angles(it)
                    Line(circle=(scx, scy, sr, a1, a2), width=width)
            elif isinstance(it, RectItem):
                corners = rect_corners(it)
                screen_pts = []
                for i in range(0, 8, 2):
                    sx, sy = self.to_screen_coords(corners[i], corners[i + 1])
                    screen_pts.extend([sx, sy])
                Line(points=screen_pts, width=width, close=True)
            elif isinstance(it, PolyItem):
                pts = poly_points(it)
                screen_pts = []
                for i in range(0, len(pts), 2):
                    sx, sy = self.to_screen_coords(pts[i], pts[i + 1])
                    screen_pts.extend([sx, sy])
                Line(points=screen_pts, width=width, close=True)
            elif isinstance(it, TextItem):
                cxw, cyw = item_center(it)
                scx, scy = self.to_screen_coords(cxw, cyw)
                tex = self._text_texture(
                    it.text,
                    max(10.0, float(it.font_size) * max(self.zoom_level, 0.35)),
                    color,
                    bool(getattr(it, "bold", False)),
                    font_ref=it.font_ref,
                )
                if tex is not None and tex.width >= 1:
                    tw, th = tex.size
                    px = scx - tw * 0.5
                    py = scy - th * 0.5
                    PushMatrix()
                    Rotate(angle=it.rotation, origin=(scx, scy))
                    Color(1, 1, 1, 1)
                    Rectangle(texture=tex, pos=(px, py), size=(tw, th))
                    if tuple(color) == tuple(SELECTED):
                        Color(*SELECTED)
                        Line(rectangle=(px - 4, py - 3, tw + 8, th + 6), width=1.2)
                    PopMatrix()

    # ----- CELL support -----
    def _serialize_item(self, it) -> dict:
        self._ensure_item_layer(it)
        base = {
            "color": list(it.color),
            "width": float(it.width),
            "layer_name": str(getattr(it, "layer_name", self.active_layer) or self.active_layer),
        }
        if isinstance(it, LineItem):
            base.update({"type": "line", "x1": it.x1, "y1": it.y1, "x2": it.x2, "y2": it.y2})
        elif isinstance(it, CircleItem):
            base.update({"type": "circle", "cx": it.cx, "cy": it.cy, "r": it.r})
        elif isinstance(it, ArcItem):
            base.update({"type": "arc", "cx": it.cx, "cy": it.cy, "r": it.r, "a_start": it.a_start, "a_end": it.a_end})
        elif isinstance(it, RectItem):
            base.update({"type": "rect", "x1": it.x1, "y1": it.y1, "x2": it.x2, "y2": it.y2, "rotation": it.rotation})
        elif isinstance(it, PolyItem):
            base.update({"type": "poly", "cx": it.cx, "cy": it.cy, "r": it.r, "sides": it.sides, "rotation": it.rotation})
        elif isinstance(it, BoundaryItem):
            base.update({"type": "boundary", "pts": list(it.pts), "closed": bool(it.closed)})
        elif isinstance(it, TextItem):
            base.update({
                "type": "text",
                "x": it.x,
                "y": it.y,
                "text": it.text,
                "font_ref": it.font_ref,
                "font_size": it.font_size,
                "rotation": it.rotation,
                "text_w": it.text_w,
                "text_h": it.text_h,
                "align": getattr(it, "align", "right"),
                "bold": bool(getattr(it, "bold", False)),
            })
        else:
            raise ValueError("Unsupported item type")
        return base

    def _deserialize_item(self, rec: dict):
        t = rec.get("type")
        color = tuple(rec.get("color", TEXT_MAIN))
        width = float(rec.get("width", 2.0))
        layer_name = str(rec.get("layer_name") or self._color_layer_name(color))
        if t == "line":
            return LineItem(color=color, width=width, layer_name=layer_name, x1=rec["x1"], y1=rec["y1"], x2=rec["x2"], y2=rec["y2"])
        if t == "circle":
            return CircleItem(color=color, width=width, layer_name=layer_name, cx=rec["cx"], cy=rec["cy"], r=rec["r"])
        if t == "arc":
            return ArcItem(color=color, width=width, layer_name=layer_name, cx=rec["cx"], cy=rec["cy"], r=rec["r"], a_start=rec["a_start"], a_end=rec["a_end"])
        if t == "rect":
            return RectItem(color=color, width=width, layer_name=layer_name, x1=rec["x1"], y1=rec["y1"], x2=rec["x2"], y2=rec["y2"], rotation=rec.get("rotation", 0.0))
        if t == "poly":
            return PolyItem(color=color, width=width, layer_name=layer_name, cx=rec["cx"], cy=rec["cy"], r=rec["r"], sides=int(rec.get("sides", 6)), rotation=rec.get("rotation", 0.0))
        if t == "boundary":
            return BoundaryItem(color=color, width=width, layer_name=layer_name, pts=list(rec.get("pts", [])), closed=bool(rec.get("closed", True)))
        if t == "text":
            txt = str(rec.get("text", ""))
            fsize = float(rec.get("font_size", 24.0))
            tw = float(rec.get("text_w", estimate_text_world_box(txt, fsize)[0]))
            th = float(rec.get("text_h", estimate_text_world_box(txt, fsize)[1]))
            return TextItem(color=color, width=width, layer_name=layer_name,
                            x=rec.get("x", 0.0), y=rec.get("y", 0.0),
                            text=txt, font_ref=str(rec.get("font_ref", APP_FONT)),
                            font_size=fsize, rotation=float(rec.get("rotation", 0.0)),
                            text_w=tw, text_h=th,
                            align=str(rec.get("align", "right")),
                            bold=bool(rec.get("bold", False)))
        raise ValueError(f"Unknown cell item type: {t}")

    def _drawing_payload(self, doc_name: str = "") -> dict:
        self._assign_items_to_layers_by_color()
        return {
            "format": "mapstation-drawing",
            "version": 1,
            "name": self._sanitize_doc_name(doc_name or self._doc_display_name()),
            "utm_zone": int(self.utm_zone),
            "utm_hemisphere": str(self.utm_hemisphere),
            "poly_sides": int(self.poly_sides),
            "label_mode": int(self.label_mode),
            "active_layer": str(self.active_layer),
            "layers": {nm: {"visible": bool(info.get("visible", True)), "locked": bool(info.get("locked", False)), "color": list(self._norm_rgba(info.get("color", self.current_color)))} for nm, info in self.layers.items()},
            "items": [self._serialize_item(it) for it in self.items],
        }

    def _load_drawing_payload(self, data: dict) -> List[BaseItem]:
        records = data.get("items", [])
        if not isinstance(records, list):
            raise ValueError("Drawing file has no valid items list")
        items = [self._deserialize_item(rec) for rec in records if isinstance(rec, dict)]
        return items

    def _write_drawing_file(self, path: str, doc_name: str = "") -> Tuple[bool, str]:
        if not self.items:
            return False, "No items to save"
        folder = os.path.dirname(path)
        if folder:
            os.makedirs(folder, exist_ok=True)
        payload = self._drawing_payload(doc_name or os.path.splitext(os.path.basename(path))[0])
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        self.current_doc_path = path
        self.status_text = f"Saved: {os.path.basename(path)} | py"
        return True, path

    def save_current_drawing(self) -> Tuple[bool, str]:
        if self.current_doc_path:
            return self._write_drawing_file(self.current_doc_path)
        auto_name = self._next_available_doc_name("drawing")
        path = os.path.join(self._ensure_drawing_dir(), f"{auto_name}{DRAWING_EXT}")
        return self._write_drawing_file(path, auto_name)

    def save_current_drawing_as(self, name: str) -> Tuple[bool, str]:
        safe_name = self._sanitize_doc_name(name or self._next_available_doc_name("drawing"))
        path = os.path.join(self._ensure_drawing_dir(), f"{safe_name}{DRAWING_EXT}")
        return self._write_drawing_file(path, safe_name)

    def export_current_drawing_as(self, name: str) -> Tuple[bool, str]:
        safe_name = self._sanitize_doc_name(name or f"{self._doc_display_name()}_export")
        path = os.path.join(self._ensure_export_dir(), f"{safe_name}{DRAWING_EXT}")
        old_path = self.current_doc_path
        ok, msg = self._write_drawing_file(path, safe_name)
        self.current_doc_path = old_path
        if ok:
            self.status_text = f"Exported: {os.path.basename(path)} | py"
        return ok, msg

    def list_drawing_files(self, include_exports: bool = False) -> List[str]:
        folders = [self._ensure_drawing_dir()]
        if include_exports:
            folders.append(self._ensure_export_dir())
        seen_folders = []
        for folder in folders:
            if folder not in seen_folders:
                seen_folders.append(folder)
        files = []
        seen_files = set()
        for folder in seen_folders:
            for name in os.listdir(folder):
                if not name.lower().endswith(DRAWING_EXT):
                    continue
                path = os.path.join(folder, name)
                if path in seen_files:
                    continue
                seen_files.add(path)
                files.append(path)
        return sorted(files, key=lambda s: s.lower())

    def open_drawing_file(self, path: str) -> Tuple[bool, str]:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        items = self._load_drawing_payload(data)
        self.items = items
        self.selected = []
        self.undo_stack = []
        self.redo_stack = []
        self.utm_zone = int(data.get("utm_zone", self.utm_zone))
        self.utm_hemisphere = str(data.get("utm_hemisphere", self.utm_hemisphere))
        self.poly_sides = int(data.get("poly_sides", self.poly_sides))
        self.label_mode = int(data.get("label_mode", self.label_mode))
        self.layers = {}
        for nm, info in dict(data.get("layers", {})).items():
            if isinstance(info, dict):
                self._ensure_layer(nm, info.get("color", self.current_color), info.get("visible", True), info.get("locked", False))
        self._assign_items_to_layers_by_color(force_by_color=(not bool(data.get("layers"))))
        want_active = str(data.get("active_layer") or self.active_layer)
        if want_active in self.layers and self._layer_visible(want_active) and not self._layer_locked(want_active):
            self.active_layer = want_active
        elif self.active_layer not in self.layers:
            self.active_layer = next(iter(self.layers.keys()), "Default")
        self.layer_selected_name = self.active_layer
        self._sync_current_color_from_active_layer()
        self.current_doc_path = path
        self._reset_pending(keep_cell=False)
        self.status_text = f"Opened: {os.path.basename(path)} | py"
        self._redraw()
        return True, path

    def import_drawing_file(self, path: str) -> Tuple[bool, str]:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        for nm, info in dict(data.get("layers", {})).items():
            if isinstance(info, dict):
                self._ensure_layer(nm, info.get("color", self.current_color), info.get("visible", True), info.get("locked", False))
        items = self._load_drawing_payload(data)
        if not items:
            return False, "No items to import"
        self._assign_items_to_layers_by_color(items=items, force_by_color=(not bool(data.get("layers"))))
        self._add_group(items, preserve_style=True)
        self.status_text = f"Imported: {os.path.basename(path)} ({len(items)} items) | py"
        return True, path

    def save_current_as_cell(self, name: str) -> Tuple[bool, str]:
        if not self.items:
            return False, "No items to save"
        safe_name = self._sanitize_cell_name(name)
        payload = {
            "format": "pystation-cell",
            "version": 1,
            "name": safe_name,
            "items": [self._serialize_item(it) for it in self.items],
        }
        path = os.path.join(self._ensure_cell_dir(), f"{safe_name}.pscell")
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        self.status_text = f"Cell saved: {safe_name}"
        return True, path

    def list_cell_files(self) -> List[str]:
        folder = self._ensure_cell_dir()
        files = []
        for name in os.listdir(folder):
            if name.lower().endswith(".pscell"):
                files.append(os.path.join(folder, name))
        return sorted(files)

    def load_cell_file(self, path: str) -> Tuple[str, List[dict]]:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        records = data.get("items", [])
        if not isinstance(records, list) or not records:
            raise ValueError("Cell file has no drawable items")
        name = str(data.get("name") or os.path.splitext(os.path.basename(path))[0])
        return name, [dict(r) for r in records if isinstance(r, dict)]

    def cancel_pending_cell(self):
        if self._pending_cell_records:
            self.status_text = "Cell insert cancelled"
        self._pending_cell_records = None
        self._pending_cell_name = ""
        self.canvas.after.clear()
        self._redraw()

    def begin_insert_cell(self, name: str, records: List[dict]):
        self._reset_pending(keep_cell=False)
        self._pending_cell_records = [dict(r) for r in records]
        self._pending_cell_name = str(name or "cell")
        self.status_text = f"Cell insert: {self._pending_cell_name} - tap insertion point"

    def _cell_bounds(self, records: List[dict]) -> Tuple[float, float, float, float]:
        xs = []
        ys = []
        for rec in records:
            it = self._deserialize_item(rec)
            x1, y1, x2, y2 = item_bounds(it)
            xs.extend([x1, x2])
            ys.extend([y1, y2])
        return min(xs), min(ys), max(xs), max(ys)

    def _translated_cell_records(self, records: List[dict], target_x: float, target_y: float) -> List[dict]:
        min_x, min_y, _max_x, _max_y = self._cell_bounds(records)
        dx = target_x - min_x
        dy = target_y - min_y
        out = []
        for rec in records:
            item = self._deserialize_item(rec)
            item_translate(item, dx, dy)
            out.append(self._serialize_item(item))
        return out

    def _preview_pending_cell(self, x: float, y: float):
        if not self._pending_cell_records:
            return
        for rec in self._translated_cell_records(self._pending_cell_records, x, y):
            try:
                it = self._deserialize_item(rec)
            except Exception:
                continue
            self._draw_item_geometry(self.canvas.after, it, color=PREVIEW, width=max(1.5, it.width * self.zoom_level), draw_vertex_rings=False)
        self._draw_snap_marker()

    def _insert_pending_cell(self, x: float, y: float):
        if not self._pending_cell_records:
            return False
        new_items = []
        for rec in self._translated_cell_records(self._pending_cell_records, x, y):
            new_items.append(self._deserialize_item(rec))
        self._add_group(new_items, preserve_style=True)
        name = self._pending_cell_name
        self._pending_cell_records = None
        self._pending_cell_name = ""
        self.status_text = f"Cell inserted: {name} ({len(new_items)} items)"
        return True

    @safe
    def on_touch_down(self, touch):
        if not self.collide_point(*touch.pos):
            return super().on_touch_down(touch)

        btn = getattr(touch, 'button', '')
        if btn == 'scrollup':
            self.zoom_in()
            return True
        if btn == 'scrolldown':
            self.zoom_out()
            return True

        mods = list(Window.modifiers) if Window else []
        if btn == 'middle' or (btn == 'left' and 'ctrl' in mods):
            self._panning = True
            self._pan_start = (touch.x, touch.y)
            touch.grab(self)
            self._touches[touch.uid] = touch
            return True

        touch.grab(self)
        self._touches[touch.uid] = touch
        if len(self._touches) >= 2:
            self._begin_pinch()
            return True

        x, y = self.to_canvas_coords(*touch.pos)
        x, y = self._snap(x, y, touch.pos)
        t = self.tool

        if self._pending_cell_records:
            self._insert_pending_cell(x, y)
            return True
        if self._pending_text_spec:
            self._place_pending_text(x, y)
            return True

        self.show_coord_info(x, y)

        if t == Tool.SELECT:
            multi = any(m in mods for m in ("shift", "ctrl"))
            it = self._pick(x, y)
            if it is None:
                if self.selected:
                    self.selected = []
                    self.status_text = "Selection cleared"
                else:
                    self.status_text = "Nothing selected"
            elif multi:
                if self._is_sel(it):
                    self.selected = [s for s in self.selected if s is not it]
                    self.status_text = f"Selection updated: {len(self.selected)} item(s)"
                else:
                    self.selected.append(it)
                    self.status_text = f"Selection updated: {len(self.selected)} item(s)"
            else:
                self.selected = [it]
                self.status_text = "1 selected"
            self._redraw()
            return True

        if t == Tool.DELETE:
            it = self._pick(x, y)
            if it is not None:
                if self._item_layer_locked(it):
                    self.status_text = f"Layer locked: {self._ensure_item_layer(it)}"
                else:
                    self._remove(it)
                    self.selected = [s for s in self.selected if s is not it]
                    self.status_text = "Deleted"
            else:
                self.status_text = "Nothing under cursor"
            self._redraw()
            return True

        if t in (Tool.MOVE, Tool.COPY, Tool.ROTATE):
            it = self._pick(x, y)
            if it is None:
                self.status_text = "Nothing under cursor"
                return True
            if self._item_layer_locked(it):
                self.status_text = f"Layer locked: {self._ensure_item_layer(it)}"
                return True
            if t == Tool.COPY:
                it = copy.deepcopy(it)
                self.items.append(it)
            self._drag_item = it
            self._drag_before = self._snap_state(it)
            self._drag_last = (x, y)
            self._drag_moved = False
            cx, cy = item_center(it)
            self._drag_ref_ang = ang(cx, cy, x, y)
            self.status_text = f"{t.name.title()} - drag"
            self._redraw()
            return True

        if t in (Tool.LINE, Tool.CHAIN, Tool.BOUNDARY, Tool.LINE_LA, Tool.CIRCLE_CR, Tool.CIRCLE_R, Tool.CIRCLE_2P, Tool.ARC_3P, Tool.RECT, Tool.POLY) and not self._can_draw_on_active_layer():
            self._redraw()
            return True

        if t == Tool.MEASURE:
            if self._p1 is None:
                self._p1 = (x, y)
                self.status_text = f"Measure - first point set | SNAP={self._snap_info} | tap second point"
            else:
                x1, y1 = self._p1
                self.status_text = (f"D={dist(x1, y1, x, y):.2f} | "
                                    f"A={ang(x1, y1, x, y):.2f} deg | "
                                    f"dX={x - x1:.2f} | dY={y - y1:.2f}")
                self._p1 = None
                self.canvas.after.clear()
            self._redraw()
            return True

        if t == Tool.LINE:
            if self._p1 is None:
                self._p1 = (x, y)
                self.status_text = f"Line - start set | SNAP={self._snap_info} | tap end point"
            else:
                x1, y1 = self._p1
                x, y = self._apply_ortho_after_snap(x1, y1, x, y)
                ln = dist(x1, y1, x, y)
                if ln <= self._min_geom_tol():
                    self._p1 = None
                    self.status_text = "Line ignored: points too close"
                    self.canvas.after.clear()
                    self._redraw()
                    return True
                self._add(LineItem(x1=x1, y1=y1, x2=x, y2=y), redraw=False)
                self._p1 = None
                self.status_text = f"Line created | L={ln:.2f} | A={ang(x1, y1, x, y):.2f} deg | SNAP={self._snap_info} | tap start point"
                self._redraw()
            return True

        if t in (Tool.CHAIN, Tool.BOUNDARY):
            if self._bpts:
                lx, ly = self._bpts[-2], self._bpts[-1]
                x, y = self._apply_ortho_after_snap(lx, ly, x, y)
                if dist(lx, ly, x, y) <= self._snap_world_tol(14.0):
                    self.status_text = f"Duplicate point ignored | SNAP={self._snap_info}"
                    self.canvas.after.clear()
                    self._redraw()
                    return True
            if t == Tool.BOUNDARY and len(self._bpts) >= 6 and self._snap_kind == "close":
                item = BoundaryItem(pts=list(self._bpts), closed=True)
                self._add(item, redraw=False)
                self.status_text = f"Boundary closed: {len(self._bpts) // 2} vertices, area {boundary_area(item):,.1f} m2"
                self._reset_pending(keep_cell=False)
                return True
            self._bpts.extend([x, y])
            self.status_text = f"P{len(self._bpts) // 2} set | SNAP={self._snap_info} | tap next, then Finish"
            self.canvas.after.clear()
            self._redraw()
            return True

        if t == Tool.LINE_LA:
            self._p1 = (x, y)
            self.status_text = f"Length/Angle - start set | SNAP={self._snap_info} | open Key-in and press Place"
            self._redraw()
            return True

        if t == Tool.CIRCLE_CR:
            if self._p1 is None:
                self._p1 = (x, y)
                self.status_text = f"Circle CR - center set | SNAP={self._snap_info} | tap radius point"
            else:
                cx, cy = self._p1
                r = dist(cx, cy, x, y)
                self._p1 = None
                if r <= self._min_geom_tol():
                    self.status_text = "Circle ignored: radius too small"
                    self.canvas.after.clear()
                    self._redraw()
                    return True
                self._add(CircleItem(cx=cx, cy=cy, r=r), redraw=False)
                self.status_text = f"Circle created | R={r:.2f} | tap center"
                self._redraw()
            return True

        if t == Tool.CIRCLE_R:
            self._p1 = (x, y)
            self.status_text = f"Circle R - center set | SNAP={self._snap_info} | enter radius"
            self._redraw()
            Clock.schedule_once(lambda _dt: CircleRadiusPopup(self).open(), 0)
            return True

        if t == Tool.CIRCLE_2P:
            if self._p1 is None:
                self._p1 = (x, y)
                self.status_text = f"Circle 2P - first point set | SNAP={self._snap_info} | tap opposite point"
            else:
                x1, y1 = self._p1
                r = dist(x1, y1, x, y) * 0.5
                self._p1 = None
                if r <= self._min_geom_tol():
                    self.status_text = "Circle ignored: diameter too small"
                    self.canvas.after.clear()
                    self._redraw()
                    return True
                self._add(CircleItem(cx=(x1 + x) * 0.5, cy=(y1 + y) * 0.5, r=r), redraw=False)
                self.status_text = f"Circle created | D={r * 2:.2f} | tap first point"
                self._redraw()
            return True

        if t == Tool.ARC_3P:
            if self._p1 is None:
                self._p1 = (x, y)
                self.status_text = f"Arc 3P - first point set | SNAP={self._snap_info} | tap second point"
            elif self._p2 is None:
                self._p2 = (x, y)
                self.status_text = f"Arc 3P - second point set | SNAP={self._snap_info} | tap third point"
            else:
                self._make_arc(self._p1, self._p2, (x, y))
                self._p1 = self._p2 = None
                self.canvas.after.clear()
            self._redraw()
            return True

        if t == Tool.RECT:
            if self._p1 is None:
                self._p1 = (x, y)
                self.status_text = f"Rectangle - first corner set | SNAP={self._snap_info} | tap opposite corner"
            else:
                x1, y1 = self._p1
                self._p1 = None
                tol = self._min_geom_tol()
                if abs(x - x1) <= tol or abs(y - y1) <= tol:
                    self.status_text = "Rectangle ignored: size too small"
                    self.canvas.after.clear()
                    self._redraw()
                    return True
                self._add(RectItem(x1=x1, y1=y1, x2=x, y2=y), redraw=False)
                self.status_text = "Rectangle created | tap first corner"
                self._redraw()
            return True

        if t == Tool.POLY:
            if self._p1 is None:
                self._p1 = (x, y)
                self.status_text = f"Polygon - center set | SNAP={self._snap_info} | tap vertex point"
            else:
                cx, cy = self._p1
                r = dist(cx, cy, x, y)
                self._p1 = None
                if r <= max(self._min_geom_tol(), 1.0):
                    self.status_text = "Polygon ignored: radius too small"
                    self.canvas.after.clear()
                    self._redraw()
                    return True
                self._add(PolyItem(cx=cx, cy=cy, r=r, sides=self.poly_sides, rotation=ang(cx, cy, x, y)), redraw=False)
                self.status_text = f"Polygon created | sides={self.poly_sides} | tap center"
                self._redraw()
            return True

        return True

    def _make_arc(self, p1, p2, p3):
        (x1, y1), (x2, y2), (x3, y3) = p1, p2, p3
        d = 2.0 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2))
        if abs(d) < 1e-6:
            self.status_text = "3 points are collinear"
            return
        s1 = x1 * x1 + y1 * y1
        s2 = x2 * x2 + y2 * y2
        s3 = x3 * x3 + y3 * y3
        ux = (s1 * (y2 - y3) + s2 * (y3 - y1) + s3 * (y1 - y2)) / d
        uy = (s1 * (x3 - x2) + s2 * (x1 - x3) + s3 * (x2 - x1)) / d
        r = dist(ux, uy, x1, y1)
        a1, a2, a3 = ang(ux, uy, x1, y1), ang(ux, uy, x2, y2), ang(ux, uy, x3, y3)
        if (a2 - a1) % 360.0 < (a3 - a1) % 360.0:
            start, end = a1, a3
        else:
            start, end = a3, a1
        self._add(ArcItem(cx=ux, cy=uy, r=r, a_start=start, a_end=end), redraw=False)
        self.status_text = f"Arc created | R={r:.2f}"
        self._redraw()

    @safe
    def on_touch_move(self, touch):
        if touch.grab_current is not self:
            return super().on_touch_move(touch)

        self._touches[touch.uid] = touch
        if self._pinch_mode and len(self._touches) >= 2:
            self._update_pinch()
            return True

        if self._panning and self._pan_start:
            dx = touch.x - self._pan_start[0]
            dy = touch.y - self._pan_start[1]
            self.pan_x += dx
            self.pan_y += dy
            self._pan_start = (touch.x, touch.y)
            self._redraw()
            return True

        x, y = self.to_canvas_coords(*touch.pos)
        x, y = self._snap(x, y, touch.pos)
        self.show_coord_info(x, y)

        if self._drag_item is not None:
            it = self._drag_item
            self._drag_moved = True
            if self.tool in (Tool.MOVE, Tool.COPY):
                lx, ly = self._drag_last
                item_translate(it, x - lx, y - ly)
                self._drag_last = (x, y)
            elif self.tool == Tool.ROTATE:
                cx, cy = item_center(it)
                cur = ang(cx, cy, x, y)
                delta = cur - self._drag_ref_ang
                if self.ortho:
                    delta = round(delta / 15.0) * 15.0
                    if abs(delta) < 1e-9:
                        return True
                item_rotate(it, cx, cy, delta)
                self._drag_ref_ang += delta
            self._redraw()
            return True

        self.canvas.after.clear()

        if self._pending_cell_records:
            self.status_text = f"Cell insert: {self._pending_cell_name} | SNAP={self._snap_info} | tap insertion point"
            self._preview_pending_cell(x, y)
            return True

        if self._pending_text_spec:
            self.status_text = f"Text insert | SNAP={self._snap_info} | tap insertion point"
            self._preview_pending_text(x, y)
            return True

        if self._bpts and self.tool in (Tool.BOUNDARY, Tool.CHAIN):
            lx, ly = self._bpts[-2], self._bpts[-1]
            x, y = self._apply_ortho_after_snap(lx, ly, x, y)
            hint = "tap first point to close" if (self.tool == Tool.BOUNDARY and self._snap_kind == "close") else "tap next / Finish"
            self.status_text = (f"P{len(self._bpts) // 2 + 1} | "
                                f"L={dist(lx, ly, x, y):.2f} | "
                                f"AZ={edge_azimuth(lx, ly, x, y):.2f} deg | "
                                f"SNAP={self._snap_info} | {hint}")
            self._preview_poly(self._bpts + [x, y], close=(self.tool == Tool.BOUNDARY))
            return True

        if self._p1 is None:
            self.status_text = f"{self._tool_prompt()} | SNAP={self._snap_info}"
            self._draw_snap_marker()
            return True

        x1, y1 = self._p1
        t = self.tool

        if t in (Tool.LINE, Tool.CHAIN, Tool.MEASURE):
            if t != Tool.MEASURE:
                x, y = self._apply_ortho_after_snap(x1, y1, x, y)
            self.status_text = f"L={dist(x1, y1, x, y):.2f} | A={ang(x1, y1, x, y):.2f} deg | SNAP={self._snap_info}"
            self._preview_line(x1, y1, x, y)
        elif t == Tool.CIRCLE_CR:
            r = dist(x1, y1, x, y)
            self.status_text = f"R={r:.2f} | SNAP={self._snap_info}"
            self._preview_circle(x1, y1, r)
            self._preview_line(x1, y1, x, y)
        elif t == Tool.CIRCLE_R:
            self.status_text = f"Circle R | center fixed | open radius input | SNAP={self._snap_info}"
            self._draw_snap_marker()
        elif t == Tool.CIRCLE_2P:
            r = dist(x1, y1, x, y) * 0.5
            self.status_text = f"D={r * 2:.2f} | R={r:.2f} | SNAP={self._snap_info}"
            self._preview_circle((x1 + x) * 0.5, (y1 + y) * 0.5, r)
            self._preview_line(x1, y1, x, y)
        elif t == Tool.RECT:
            self.status_text = f"W={abs(x - x1):.2f} | H={abs(y - y1):.2f} | SNAP={self._snap_info}"
            self._preview_poly([x1, y1, x, y1, x, y, x1, y])
        elif t == Tool.POLY:
            r = dist(x1, y1, x, y)
            self.status_text = f"R={r:.2f} | n={self.poly_sides} | SNAP={self._snap_info}"
            self._preview_poly(poly_points(PolyItem(cx=x1, cy=y1, r=r, sides=self.poly_sides, rotation=ang(x1, y1, x, y))))
        elif t == Tool.ARC_3P and self._p2 is not None:
            self.status_text = f"Arc 3P | SNAP={self._snap_info} | tap third point"
            self._preview_line(x1, y1, self._p2[0], self._p2[1])
            self._preview_line(self._p2[0], self._p2[1], x, y)
        elif t == Tool.ARC_3P:
            self.status_text = f"Arc 3P | SNAP={self._snap_info} | tap second point"
            self._preview_line(x1, y1, x, y)
        else:
            self._draw_snap_marker()
        return True

    @safe
    def on_touch_up(self, touch):
        if touch.grab_current is not self:
            return super().on_touch_up(touch)
        touch.ungrab(self)
        self._touches.pop(touch.uid, None)

        if self._pinch_mode:
            if len(self._touches) < 2:
                self._end_pinch()
            return True

        if self._panning:
            self._panning = False
            self._pan_start = None
            return True

        if self._drag_item is not None:
            it = self._drag_item
            after = self._snap_state(it)
            if self.tool == Tool.COPY and not self._drag_moved:
                try:
                    self.items.remove(it)
                except ValueError:
                    pass
                self.status_text = "Copy cancelled (no drag)"
            elif self.tool == Tool.COPY:
                self._push(("add", it, len(self.items) - 1))
                self.status_text = "Copied"
            elif after != self._drag_before:
                self._push(("mod", it, self._drag_before, after))
            self._drag_item = None
            self._drag_before = None
            self._redraw()
        return True

    # ----- survey labels (derived view: nothing is stored) -----
    def _render_labels(self, it: BoundaryItem):
        if self.label_mode <= 0 or not isinstance(it, BoundaryItem):
            return
        n = boundary_count(it)
        if n < 2:
            return

        if self.label_mode >= 1:
            for i in range(n):
                tex = self._text_texture(f"P{i + 1}", 13, LBL_VERTEX, True)
                if tex is None or tex.width < 1:
                    continue
                bx, by = vertex_label_dir(it, i)
                sx, sy = self.to_screen_coords(it.pts[2 * i], it.pts[2 * i + 1])
                off = tex.height * 0.5 + 12
                lx, ly = sx + bx * off, sy + by * off
                tw, th = tex.size
                with self.canvas:
                    Color(*LBL_CHIP)
                    Rectangle(pos=(lx - tw * 0.5 - 4, ly - th * 0.5 - 2), size=(tw + 8, th + 4))
                    Color(1, 1, 1, 1)
                    Rectangle(texture=tex, pos=(lx - tw * 0.5, ly - th * 0.5), size=(tw, th))

        if self.label_mode == 2:
            for x1, y1, x2, y2 in boundary_edges(it):
                L = dist(x1, y1, x2, y2)
                tex = self._text_texture(f"{L:.2f} m", 12, LBL_EDGE)
                if tex is None or tex.width < 1:
                    continue
                sx1, sy1 = self.to_screen_coords(x1, y1)
                sx2, sy2 = self.to_screen_coords(x2, y2)
                if dist(sx1, sy1, sx2, sy2) < tex.width + 8:
                    continue
                read, ux, uy = edge_label_geom(x1, y1, x2, y2)
                mx = (sx1 + sx2) * 0.5 + ux * (tex.height * 0.5 + 5)
                my = (sy1 + sy2) * 0.5 + uy * (tex.height * 0.5 + 5)
                tw, th = tex.size
                with self.canvas:
                    Color(1, 1, 1, 1)
                    PushMatrix()
                    Rotate(angle=read, origin=(mx, my))
                    Rectangle(texture=tex, pos=(mx - tw * 0.5, my - th * 0.5), size=(tw, th))
                    PopMatrix()

            if it.closed:
                a = boundary_area(it)
                if a > 0:
                    cxw, cyw = boundary_centroid(it)
                    tex = self._text_texture(f"{a:,.1f} m2", 15, LBL_AREA, True)
                    if tex is not None and tex.width >= 1:
                        sx, sy = self.to_screen_coords(cxw, cyw)
                        tw, th = tex.size
                        with self.canvas:
                            Color(*LBL_CHIP)
                            Rectangle(pos=(sx - tw * 0.5 - 6, sy - th * 0.5 - 3), size=(tw + 12, th + 6))
                            Color(1, 1, 1, 1)
                            Rectangle(texture=tex, pos=(sx - tw * 0.5, sy - th * 0.5), size=(tw, th))

    @safe
    def _redraw(self, *a):
        self.canvas.before.clear()
        with self.canvas.before:
            Color(*CANVAS_BG)
            Rectangle(pos=self.pos, size=self.size)

            step = dp(25) * self.zoom_level
            n = 0
            gx = self.center_x + self.pan_x
            while gx <= self.right:
                Color(*(GRID_MAJOR if n % 4 == 0 else GRID_MINOR))
                Line(points=[gx, self.y, gx, self.top], width=1)
                gx += step; n += 1

            n = 0
            gx = self.center_x + self.pan_x - step
            while gx >= self.x:
                n += 1
                Color(*(GRID_MAJOR if n % 4 == 0 else GRID_MINOR))
                Line(points=[gx, self.y, gx, self.top], width=1)
                gx -= step

            n = 0
            gy = self.center_y + self.pan_y
            while gy <= self.top:
                Color(*(GRID_MAJOR if n % 4 == 0 else GRID_MINOR))
                Line(points=[self.x, gy, self.right, gy], width=1)
                gy += step; n += 1

            n = 0
            gy = self.center_y + self.pan_y - step
            while gy >= self.y:
                n += 1
                Color(*(GRID_MAJOR if n % 4 == 0 else GRID_MINOR))
                Line(points=[self.x, gy, self.right, gy], width=1)
                gy -= step

        self.canvas.clear()
        with self.canvas:
            for it in self.items:
                if not self._item_layer_visible(it):
                    continue
                sel = self._is_sel(it) or (it is self._drag_item)
                color = SELECTED if sel else it.color
                width = (it.width + (1.4 if sel else 0.0)) * self.zoom_level
                self._draw_item_geometry(self.canvas, it, color=color, width=width, draw_vertex_rings=True)

            if self.label_mode > 0:
                for it in self.items:
                    if self._item_layer_visible(it) and isinstance(it, BoundaryItem):
                        self._render_labels(it)

            if len(self._bpts) >= 4:
                spts = []
                for i in range(0, len(self._bpts), 2):
                    sx, sy = self.to_screen_coords(self._bpts[i], self._bpts[i + 1])
                    spts.extend([sx, sy])
                Color(*PREVIEW)
                Line(points=spts, width=1.5, dash_length=6, dash_offset=4, close=(self.tool == Tool.BOUNDARY))
                Color(*LBL_VERTEX)
                for i in range(0, len(self._bpts), 2):
                    sx, sy = self.to_screen_coords(self._bpts[i], self._bpts[i + 1])
                    Line(circle=(sx, sy, dp(5)), width=1.4)

            if self._p1 is not None:
                sx, sy = self.to_screen_coords(*self._p1)
                Color(*LBL_VERTEX)
                Line(circle=(sx, sy, dp(6)), width=1.5)
            if self._p2 is not None:
                sx, sy = self.to_screen_coords(*self._p2)
                Color(*LBL_VERTEX)
                Line(circle=(sx, sy, dp(6)), width=1.5)

# ===== Popups =====
def _dark_input(text, filt="float"):
    return TextInput(text=text, multiline=False, input_filter=filt,
                     background_color=(0.16, 0.19, 0.23, 1),
                     foreground_color=TEXT_MAIN, cursor_color=BTN_ACTIVE,
                     size_hint_y=None, height=dp(42), padding=[dp(8)] * 4)

class TextInsertPopup(Popup):
    def __init__(self, cv: DrawingCanvas, **kw):
        kw.setdefault("auto_dismiss", False)
        super().__init__(**kw)
        self.cv = cv
        self.title = "Text / Font"
        self.size_hint = (0.94, 0.88)
        self.background = ""
        self.background_color = PANEL_BG
        self.separator_color = BTN_ACTIVE
        self.title_color = TEXT_MAIN
        self.font_map: Dict[str, str] = {}
        self._repair_guard = False
        self._prev_softinput_mode = None

        outer = BoxLayout(orientation="vertical", spacing=dp(8), padding=dp(10))
        self.sc = ScrollView(do_scroll_x=False, bar_width=dp(3), scroll_type=['bars', 'content'])
        root = BoxLayout(orientation="vertical", spacing=dp(8), padding=[dp(4), dp(2), dp(4), dp(8)], size_hint_y=None)
        root.bind(minimum_height=root.setter("height"))

        root.add_widget(Label(text="Tip: Persian font and RTL engine are ready", color=STATUS_FG, size_hint_y=None, height=dp(18), font_size="10sp"))
        root.add_widget(Label(text="Text content", color=BTN_ACTIVE, bold=True, size_hint_y=None, height=dp(22), font_size="13sp"))
        self.text_in = TextInput(text=FA_SAMPLE_TEXT, multiline=True,
                                 background_color=(0.16, 0.19, 0.23, 1),
                                 foreground_color=TEXT_MAIN, cursor_color=BTN_ACTIVE,
                                 size_hint_y=None, height=dp(96), padding=[dp(8)] * 4)
        root.add_widget(self.text_in)
        try:
            if hasattr(self.text_in, "base_direction"):
                self.text_in.base_direction = "rtl"
        except Exception:
            pass
        try:
            if hasattr(self.text_in, "halign"):
                self.text_in.halign = "right"
        except Exception:
            pass

        row1 = GridLayout(cols=2, spacing=dp(8), size_hint_y=None, height=dp(120))
        row1.add_widget(Label(text="Font", color=TEXT_MAIN))
        self.font_spin = Spinner(text="", values=(), size_hint_y=None, height=dp(38), background_color=BTN_IDLE, color=TEXT_MAIN)
        row1.add_widget(self.font_spin)
        row1.add_widget(Label(text="Text size", color=TEXT_MAIN))
        self.size_in = _dark_input("24", filt="float")
        row1.add_widget(self.size_in)
        row1.add_widget(Label(text="Align", color=TEXT_MAIN))
        self.align_spin = Spinner(text="Right", values=("Right", "Center", "Left"), size_hint_y=None, height=dp(38), background_color=BTN_IDLE, color=TEXT_MAIN)
        row1.add_widget(self.align_spin)
        root.add_widget(row1)

        row2 = GridLayout(cols=2, spacing=dp(8), size_hint_y=None, height=dp(120))
        row2.add_widget(Label(text="Insert angle (deg)", color=TEXT_MAIN))
        self.rot_in = _dark_input("0", filt="float")
        row2.add_widget(self.rot_in)
        row2.add_widget(Label(text="Weight", color=TEXT_MAIN))
        self.weight_spin = Spinner(text="Regular", values=("Regular", "Bold"), size_hint_y=None, height=dp(38), background_color=BTN_IDLE, color=TEXT_MAIN)
        row2.add_widget(self.weight_spin)
        row2.add_widget(Label(text="Text color", color=TEXT_MAIN))
        self.color_spin = Spinner(text=self.cv._layer_color_name(self.cv.current_color), values=tuple(n for n, _c in COLOR_PALETTE), size_hint_y=None, height=dp(38), background_color=BTN_IDLE, color=TEXT_MAIN)
        row2.add_widget(self.color_spin)
        root.add_widget(row2)

        root.add_widget(Label(text="Preview", color=TEXT_MAIN, size_hint_y=None, height=dp(20), font_size="12sp"))
        self.preview = Label(text=FA_SAMPLE_PREVIEW, color=TEXT_MAIN, size_hint_y=None, height=dp(42), halign="right", valign="middle")
        self.preview.bind(size=lambda w, v: setattr(w, "text_size", v))
        root.add_widget(self.preview)

        root.add_widget(Label(text="Install font from file path (.ttf / .otf)", color=BTN_ACTIVE, bold=True, size_hint_y=None, height=dp(20), font_size="11sp"))
        self.font_path_in = _dark_input("", filt=None)
        root.add_widget(self.font_path_in)
        self.msg = Label(text="", color=STATUS_FG, size_hint_y=None, height=dp(40), font_size="10sp", halign="center", valign="middle")
        self.msg.bind(size=lambda w, v: setattr(w, "text_size", v))
        root.add_widget(self.msg)

        self.sc.add_widget(root)
        outer.add_widget(self.sc)

        row_btn1 = GridLayout(cols=2, spacing=dp(8), size_hint_y=None, height=dp(44))
        b_refresh = TextButton(text="Refresh Fonts", bg=BTN_NEUTRAL, height=dp(44))
        b_refresh.bind(on_release=lambda *_: self.refresh_fonts())
        row_btn1.add_widget(b_refresh)
        b_install = TextButton(text="Install Font", bg=BTN_EDIT, height=dp(44))
        b_install.bind(on_release=lambda *_: self.install_font())
        row_btn1.add_widget(b_install)
        outer.add_widget(row_btn1)

        row_btn2 = GridLayout(cols=2, spacing=dp(8), size_hint_y=None, height=dp(44))
        b_place = TextButton(text="Place on Canvas", bg=BTN_ACTIVE, height=dp(44))
        b_place.bind(on_release=lambda *_: self.place_text())
        row_btn2.add_widget(b_place)
        b_close = TextButton(text="Close", bg=BTN_NEUTRAL, height=dp(44))
        b_close.bind(on_release=lambda *_: self.dismiss())
        row_btn2.add_widget(b_close)
        outer.add_widget(row_btn2)

        self.text_in.bind(text=lambda *_: self._on_text_change())
        self.text_in.bind(focus=self._on_text_focus)
        self.font_spin.bind(text=lambda *_: self.update_preview())
        self.align_spin.bind(text=lambda *_: self.update_preview())
        self.weight_spin.bind(text=lambda *_: self.update_preview())
        self.color_spin.bind(text=lambda *_: self.update_preview())
        self.bind(on_open=lambda *_: self._on_popup_open())
        self.bind(on_dismiss=lambda *_: self._on_popup_dismiss())
        self.refresh_fonts()
        self.content = outer

    def _preferred_font_label(self) -> str:
        for name in ("Vazir Reg", "Vazir Bold", "UI Default", "Vazirmatn Regular", "Vazirmatn Bold"):
            if name in self.font_map:
                return name
        for name in self.font_map.keys():
            if "vazir" in name.lower():
                return name
        return next(iter(self.font_map.keys()), "UI Default")

    def _focus_text_box(self, *_a):
        try:
            self.text_in.focus = True
            if hasattr(self.text_in, 'cursor'):
                self.text_in.cursor = (len(self.text_in.text), 0)
        except Exception:
            pass
        try:
            self.sc.scroll_y = 1.0
        except Exception:
            pass

    def _on_popup_open(self):
        try:
            self._prev_softinput_mode = getattr(Window, 'softinput_mode', None)
            if hasattr(Window, 'softinput_mode'):
                Window.softinput_mode = 'below_target'
        except Exception:
            pass
        Clock.schedule_once(self._focus_text_box, 0.10)
        Clock.schedule_once(self._focus_text_box, 0.35)

    def _on_popup_dismiss(self):
        try:
            self.text_in.focus = False
        except Exception:
            pass
        try:
            if self._prev_softinput_mode and hasattr(Window, 'softinput_mode'):
                Window.softinput_mode = self._prev_softinput_mode
        except Exception:
            pass

    def _on_text_focus(self, _inst, focused):
        try:
            self.sc.do_scroll_y = not focused
        except Exception:
            pass
        if focused:
            Clock.schedule_once(self._focus_text_box, 0.05)
            self.msg.text = "Keyboard ready | type text"
        else:
            self.msg.text = self.msg.text or ""

    def _on_text_change(self):
        if self._repair_guard:
            return
        fixed = repair_mojibake_text(self.text_in.text)
        if fixed != self.text_in.text:
            self._repair_guard = True
            try:
                self.text_in.text = fixed
            finally:
                self._repair_guard = False
        self.update_preview()

    def refresh_fonts(self):
        entries = self.cv.available_text_fonts()
        self.font_map = {label: ref for label, ref in entries}
        values = [label for label, _ref in entries]
        self.font_spin.values = tuple(values)
        preferred = self._preferred_font_label()
        if (not self.font_spin.text or self.font_spin.text not in self.font_map or self.font_spin.text == "UI Default") and preferred in self.font_map:
            self.font_spin.text = preferred
        self.msg.text = f"Fonts: {len(values)} | {self.font_spin.text} | {self.color_spin.text}"
        self.update_preview()

    def install_font(self):
        ok, msg, installed_ref = install_font_file_to_project(self.font_path_in.text)
        self.msg.text = msg
        if ok:
            self.refresh_fonts()
            for label, ref in self.font_map.items():
                if normalize_font_ref(ref) == normalize_font_ref(installed_ref):
                    self.font_spin.text = label
                    break
            self.font_path_in.text = ""
            self.cv.status_text = msg

    def selected_font_ref(self) -> str:
        return normalize_font_ref(self.font_map.get(self.font_spin.text, APP_FONT))

    def selected_align(self) -> str:
        return {"Left": "left", "Center": "center", "Right": "right"}.get(self.align_spin.text, "right")

    def selected_bold(self) -> bool:
        return self.weight_spin.text == "Bold"

    def selected_color(self):
        return palette_color_by_name(self.color_spin.text)

    def update_preview(self):
        sample = repair_mojibake_text(str(self.text_in.text or "").strip()) or FA_SAMPLE_PREVIEW
        font_ref = self.selected_font_ref()
        font_name, use_bold = resolve_font_name(font_ref, self.selected_bold())
        self.preview.text = sample
        self.preview.font_name = font_name
        self.preview.bold = use_bold
        self.preview.color = self.selected_color()
        self.preview.halign = {"left": "left", "center": "center", "right": "right"}[self.selected_align()]
        self.preview.text_size = self.preview.size
        self.text_in.font_name = font_name

    def place_text(self):
        try:
            size = float(self.size_in.text)
        except Exception:
            self.msg.text = "Invalid text size"
            return
        try:
            rotation = float(self.rot_in.text)
        except Exception:
            rotation = 0.0
        if self.cv.begin_text_insert(
            self.text_in.text,
            self.selected_font_ref(),
            size,
            rotation,
            align=self.selected_align(),
            bold=self.selected_bold(),
            color=self.selected_color(),
        ):
            self.dismiss()
