        self.geo_result = Label(text="", color=STATUS_FG, size_hint_y=None, height=dp(50), font_size="12sp", bold=True)
        root.add_widget(self.geo_result)

        root.add_widget(Widget(size_hint_y=None, height=dp(10)))
        root.add_widget(Label(text="Geographic (Lat/Lon) -> UTM", size_hint_y=None, height=dp(24), color=BTN_ACTIVE, bold=True, font_size="13sp"))

        grid2 = GridLayout(cols=2, spacing=dp(8), size_hint_y=None, height=dp(100))
        grid2.add_widget(Label(text="Latitude (deg)", color=TEXT_MAIN))
        self.geo_lat = _dark_input("35.6892")
        grid2.add_widget(self.geo_lat)
        grid2.add_widget(Label(text="Longitude (deg)", color=TEXT_MAIN))
        self.geo_lon = _dark_input("51.3890")
        grid2.add_widget(self.geo_lon)
        root.add_widget(grid2)

        b2 = TextButton(text="Convert to UTM", bg=BTN_ACTIVE, height=dp(44))
        b2.bind(on_release=self._geo_to_utm)
        root.add_widget(b2)

        self.utm_result = Label(text="", color=STATUS_FG, size_hint_y=None, height=dp(50), font_size="12sp", bold=True)
        root.add_widget(self.utm_result)

        root.add_widget(Widget())
