class SnapSettingsPopup(Popup):
    def __init__(self, cv: DrawingCanvas, **kw):
        super().__init__(**kw)
        self.cv = cv
        self.title = "Snap Settings"
        self.size_hint = (0.92, 0.72)
        self.background = ""
        self.background_color = PANEL_BG
        self.separator_color = BTN_ACTIVE
        self.title_color = TEXT_MAIN

        root = BoxLayout(orientation="vertical", spacing=dp(8), padding=dp(12))
        self.snap_btn = TextButton(text="", bg=BTN_WARN, height=dp(40))
        self.snap_btn.bind(on_release=lambda *_: self._toggle_master())
        root.add_widget(self.snap_btn)

        self.info_lbl = Label(text="", color=STATUS_FG, font_size="10sp", size_hint_y=None, height=dp(38), halign="left", valign="middle")
        self.info_lbl.bind(size=lambda w, v: setattr(w, "text_size", v))
        root.add_widget(self.info_lbl)

        grid = GridLayout(cols=2, spacing=dp(6), size_hint_y=None)
        grid.bind(minimum_height=grid.setter("height"))
        self.mode_btns = {}
        for kind, label in (("end", "END"), ("mid", "MID"), ("int", "INT"),
                            ("near", "NEAR"), ("center", "CENTER"), ("quad", "QUAD"),
                            ("close", "CLOSE")):
            btn = TextButton(text=label, bg=BTN_EDIT, height=dp(34))
            btn.bind(on_release=lambda *_a, k=kind: self._toggle_mode(k))
            self.mode_btns[kind] = btn
            grid.add_widget(btn)
        root.add_widget(grid)

        close_btn = TextButton(text="Close", bg=BTN_NEUTRAL, height=dp(40))
        close_btn.bind(on_release=lambda *_: self.dismiss())
        root.add_widget(close_btn)
        self.content = root
        self._sync()

    def _toggle_master(self):
        self.cv.toggle_snap()
        self._sync()

    def _toggle_mode(self, kind):
        self.cv.toggle_snap_mode(kind)
        self._sync()

    def _sync(self):
        if self.cv.snap_enabled:
            self.snap_btn.text = "SNAP ON"
            self.snap_btn.bg = list(BTN_WARN)
        else:
            self.snap_btn.text = "SNAP OFF"
            self.snap_btn.bg = list(BTN_NEUTRAL)
        self.info_lbl.text = self.cv.snap_readout
        for kind, btn in self.mode_btns.items():
            on = self.cv._snap_mode_enabled(kind) and self.cv.snap_enabled
            btn.bg = list(BTN_ACTIVE if on else BTN_NEUTRAL)

class LayerManagerPopup(Popup):
    def __init__(self, cv: DrawingCanvas, **kw):
        super().__init__(**kw)
        self.cv = cv
        self.selected_layer = cv.active_layer
        self.title = "Layers"
        self.size_hint = (0.95, 0.88)
        self.background = ""
        self.background_color = PANEL_BG
        self.separator_color = BTN_ACTIVE
        self.title_color = TEXT_MAIN

        root = BoxLayout(orientation="vertical", spacing=dp(8), padding=dp(12))
        self.info_lbl = Label(text="", color=STATUS_FG, size_hint_y=None, height=dp(42), font_size="10sp", halign="left", valign="middle")
        self.info_lbl.bind(size=lambda w, v: setattr(w, "text_size", v))
        root.add_widget(self.info_lbl)

        row1 = GridLayout(cols=2, spacing=dp(6), size_hint_y=None, height=dp(92))
        row1.add_widget(Label(text="Layer Name", color=TEXT_MAIN))
        self.name_in = _dark_input(self.selected_layer, filt=None)
        row1.add_widget(self.name_in)
        row1.add_widget(Label(text="Layer Color", color=TEXT_MAIN))
        self.color_spin = Spinner(text=self.cv._layer_color_name(self.cv.layers[self.selected_layer]["color"]), values=tuple(n for n, _c in COLOR_PALETTE), size_hint_y=None, height=dp(38), background_color=BTN_IDLE, color=TEXT_MAIN)
        row1.add_widget(self.color_spin)
        root.add_widget(row1)

        row2 = GridLayout(cols=3, spacing=dp(6), size_hint_y=None, height=dp(82))
        buttons = [
            ("Add Layer", self._add_layer, BTN_ACTIVE),
            ("Set Current", self._set_current, BTN_WARN),
            ("Move Selected", self._move_selected, BTN_EDIT),
            ("Toggle Visible", self._toggle_visible, BTN_NEUTRAL),
            ("Toggle Lock", self._toggle_lock, BTN_DANGER),
            ("Apply Color", self._apply_color, BTN_ACTIVE),
        ]
        for txt, cb, bg in buttons:
            btn = TextButton(text=txt, bg=bg, height=dp(38))
            btn.bind(on_release=lambda _b, f=cb: f())
            row2.add_widget(btn)
        root.add_widget(row2)

        sv = ScrollView(do_scroll_x=False, bar_width=dp(2))
        self.layer_col = BoxLayout(orientation="vertical", spacing=dp(6), size_hint_y=None)
        self.layer_col.bind(minimum_height=self.layer_col.setter("height"))
        sv.add_widget(self.layer_col)
        root.add_widget(sv)

        close_btn = TextButton(text="Close", bg=BTN_NEUTRAL, height=dp(40))
        close_btn.bind(on_release=lambda *_: self.dismiss())
        root.add_widget(close_btn)
        self.content = root
        self.refresh()

    def _current_target_name(self) -> str:
        nm = str(self.name_in.text or self.selected_layer or self.cv.active_layer).strip()
        return nm or self.cv.active_layer

    def _selected_color(self):
        return palette_color_by_name(self.color_spin.text)

    def _select_layer(self, name: str):
        self.selected_layer = name
        self.name_in.text = name
        self.color_spin.text = self.cv._layer_color_name(self.cv.layers[name]["color"])
        self.refresh()

    def _add_layer(self):
        ok, msg = self.cv.create_layer(self._current_target_name(), self._selected_color())
        if ok:
            self.selected_layer = msg
        else:
            self.cv.status_text = msg
        self.refresh()

    def _set_current(self):
        ok, msg = self.cv.set_active_layer(self._current_target_name())
        if ok:
            self.selected_layer = msg
        else:
            self.cv.status_text = msg
        self.refresh()

    def _move_selected(self):
        ok, msg = self.cv.move_selected_to_layer(self._current_target_name())
        if not ok:
            self.cv.status_text = msg
        else:
            self.selected_layer = msg
        self.refresh()

    def _toggle_visible(self):
        ok, msg = self.cv.toggle_layer_visible(self._current_target_name())
        if not ok:
            self.cv.status_text = msg
        else:
            self.selected_layer = msg
        self.refresh()

    def _toggle_lock(self):
        ok, msg = self.cv.toggle_layer_locked(self._current_target_name())
        if not ok:
            self.cv.status_text = msg
        else:
            self.selected_layer = msg
        self.refresh()

    def _apply_color(self):
        ok, msg = self.cv.set_layer_color(self._current_target_name(), self._selected_color())
        if not ok:
            self.cv.status_text = msg
        else:
            self.selected_layer = msg
        self.refresh()

    def refresh(self):
        self.cv._assign_items_to_layers_by_color()
        if self.selected_layer not in self.cv.layers:
            self.selected_layer = self.cv.active_layer
        info = self.cv.layers[self.selected_layer]
        self.info_lbl.text = f"Current: {self.cv.active_layer} | Selected: {self.selected_layer} | Items selected: {len(self.cv.selected)}"
        self.name_in.text = self.selected_layer
        self.color_spin.text = self.cv._layer_color_name(info.get("color", self.cv.current_color))
        self.layer_col.clear_widgets()
        for name in self.cv.layer_names():
            info = self.cv.layers[name]
            count = self.cv.layer_item_count(name)
            prefix = "*" if name == self.cv.active_layer else " "
            vis = "ON" if info.get("visible", True) else "OFF"
            lock = "LOCK" if info.get("locked", False) else "EDIT"
            col_name = self.cv._layer_color_name(info.get("color", self.cv.current_color))
            bg = BTN_ACTIVE if name == self.selected_layer else BTN_NEUTRAL
            btn = TextButton(text=f"{prefix} {name} | {vis} | {lock} | {col_name} | {count}", bg=bg, height=dp(38), font_size="10sp")
            btn.bind(on_release=lambda _b, nm=name: self._select_layer(nm))
            self.layer_col.add_widget(btn)

class SaveDrawingAsPopup(Popup):
    def __init__(self, cv: DrawingCanvas, export_mode: bool = False, **kw):
        super().__init__(**kw)
        self.cv = cv
        self.export_mode = export_mode
        self.title = "Export Drawing" if export_mode else "Save Drawing As"
        self.size_hint = (0.90, 0.48)
        self.background = ""
        self.background_color = PANEL_BG
        self.separator_color = BTN_ACTIVE
        self.title_color = TEXT_MAIN

        base_name = cv._doc_display_name()
        if base_name == "Untitled":
            base_name = cv._next_available_doc_name("drawing")
        if export_mode:
            base_name = f"{base_name}_export"
        folder = cv._ensure_export_dir() if export_mode else cv._ensure_drawing_dir()

        root = BoxLayout(orientation="vertical", spacing=dp(10), padding=dp(14))
        root.add_widget(Label(text="File name", color=TEXT_MAIN, size_hint_y=None, height=dp(24)))
        self.name_in = _dark_input(base_name, filt=None)
        root.add_widget(self.name_in)
        root.add_widget(Label(text="Target folder: py", color=BTN_ACTIVE, bold=True, font_size="11sp", size_hint_y=None, height=dp(20)))
        path_lbl = Label(text=folder, color=TEXT_DIM, font_size="10sp", size_hint_y=None, height=dp(36), halign="left", valign="middle")
        path_lbl.bind(size=lambda w, v: setattr(w, "text_size", v))
        root.add_widget(path_lbl)
        self.msg = Label(text="", color=STATUS_FG, size_hint_y=None, height=dp(28), font_size="11sp")
        root.add_widget(self.msg)

        btn = TextButton(text="Export" if export_mode else "Save", bg=BTN_ACTIVE, height=dp(44))
        btn.bind(on_release=self._save)
        root.add_widget(btn)
        close_btn = TextButton(text="Close", bg=BTN_NEUTRAL, height=dp(40))
        close_btn.bind(on_release=lambda *_: self.dismiss())
        root.add_widget(close_btn)
        self.content = root

    def _save(self, *a):
        if self.export_mode:
            ok, msg = self.cv.export_current_drawing_as(self.name_in.text)
        else:
            ok, msg = self.cv.save_current_drawing_as(self.name_in.text)
        self.msg.text = os.path.basename(msg) if ok else msg
        self.msg.color = STATUS_FG if ok else BTN_WARN
        if ok:
            self.dismiss()

class DrawingFileListPopup(Popup):
    def __init__(self, cv: DrawingCanvas, mode: str = "open", **kw):
        super().__init__(**kw)
        self.cv = cv
        self.mode = mode
        self.title = "Open Drawing" if mode == "open" else "Import Drawing"
        self.size_hint = (0.94, 0.84)
        self.background = ""
        self.background_color = PANEL_BG
        self.separator_color = BTN_ACTIVE
        self.title_color = TEXT_MAIN

        files = cv.list_drawing_files(include_exports=(mode == "import"))
        root = BoxLayout(orientation="vertical", spacing=dp(8), padding=dp(12))
        tip = "Select a saved drawing to open" if mode == "open" else "Select a drawing to import into current view"
        root.add_widget(Label(text=tip, color=TEXT_DIM, size_hint_y=None, height=dp(24), font_size="11sp"))
        root.add_widget(Label(text="Source folder: py", color=BTN_ACTIVE, bold=True, size_hint_y=None, height=dp(20), font_size="11sp"))
        path_lbl = Label(text=cv._py_dir_label(), color=TEXT_DIM, font_size="10sp", size_hint_y=None, height=dp(34), halign="left", valign="middle")
        path_lbl.bind(size=lambda w, v: setattr(w, "text_size", v))
        root.add_widget(path_lbl)
        sv = ScrollView(do_scroll_x=False, bar_width=dp(2))
        col = BoxLayout(orientation="vertical", spacing=dp(6), size_hint_y=None)
        col.bind(minimum_height=col.setter("height"))
        sv.add_widget(col)

        if not files:
            col.add_widget(Label(text=f"No {DRAWING_EXT} files found in py yet.", color=TEXT_MAIN, size_hint_y=None, height=dp(60)))
        else:
            for path in files:
                name = os.path.splitext(os.path.basename(path))[0]
                btn = TextButton(text=name, bg=BTN_ACTIVE, height=dp(40))
                btn.bind(on_release=lambda *_a, p=path: self._pick(p))
                col.add_widget(btn)

        root.add_widget(sv)
        close_btn = TextButton(text="Close", bg=BTN_NEUTRAL, height=dp(40))
        close_btn.bind(on_release=lambda *_: self.dismiss())
        root.add_widget(close_btn)
        self.content = root

    def _pick(self, path: str):
        try:
            if self.mode == "open":
                self.cv.open_drawing_file(path)
            else:
                self.cv.import_drawing_file(path)
            self.dismiss()
        except Exception as exc:
            self.cv.status_text = f"{self.mode.title()} failed: {exc}"

# ===== Tool Panel =====
class ToolPanel(ScrollView):
    def __init__(self, cv: DrawingCanvas, **kw):
        kw.setdefault("size_hint_x", None)
        kw.setdefault("width", PANEL_W)
        kw.setdefault("do_scroll_x", False)
        kw.setdefault("bar_width", dp(2))
        super().__init__(**kw)
        self.cv = cv
        self.tool_buttons: List[Tuple[IconButton, Tool]] = []
        self.color_buttons: List[ColorButton] = []

        with self.canvas.before:
            Color(*PANEL_BG)
            self._bg = Rectangle(pos=self.pos, size=self.size)
        self.bind(pos=self._up_bg, size=self._up_bg)

        col = BoxLayout(orientation="vertical", size_hint_y=None, spacing=dp(3), padding=[UI_PAD, dp(6), UI_PAD, dp(12)])
        col.bind(minimum_height=col.setter("height"))
        self.add_widget(col)

        col.add_widget(Label(text="PyStation", size_hint_y=None, height=dp(16), bold=True, font_size="9sp", color=TEXT_MAIN))

        col.add_widget(SectionLabel("VIEW"))
        g_view = self._blank_grid()
        g_view.add_widget(self._mk("Zoom In", Ico.zoom_in, BTN_NEUTRAL, cv.zoom_in))
        g_view.add_widget(self._mk("Zoom Out", Ico.zoom_out, BTN_NEUTRAL, cv.zoom_out))
        g_view.add_widget(self._mk("Fit View", Ico.fit, BTN_ACTIVE, cv.zoom_fit))
        col.add_widget(g_view)

        col.add_widget(SectionLabel("COLORS"))
        color_grid = GridLayout(cols=5, spacing=dp(2), size_hint_y=None)
        color_grid.bind(minimum_height=color_grid.setter("height"))
        for name, color in COLOR_PALETTE:
            btn = ColorButton(name, color, callback=self._set_color)
            self.color_buttons.append(btn)
            color_grid.add_widget(btn)
        col.add_widget(color_grid)
        self.color_buttons[0].set_active(True)

        col.add_widget(SectionLabel("EDIT"))
        col.add_widget(self._grid([
            (Tool.SELECT, "Select", Ico.select, BTN_IDLE),
            (Tool.MOVE,   "Move",   Ico.move,   BTN_EDIT),
            (Tool.COPY,   "Copy",   Ico.copy,   BTN_EDIT),
            (Tool.ROTATE, "Rotate", Ico.rotate, BTN_EDIT),
            (Tool.DELETE, "Delete", Ico.delete, BTN_DANGER),
        ]))

        col.add_widget(SectionLabel("DRAW"))
        g_draw = self._blank_grid()
        g_draw.add_widget(self._mk_tool(Tool.LINE, "Line", Ico.line, BTN_IDLE))
        g_draw.add_widget(self._mk_tool(Tool.CHAIN, "Polyline", Ico.chain, BTN_IDLE))
        g_draw.add_widget(self._mk_tool(Tool.BOUNDARY, "Boundary", Ico.boundary, BTN_IDLE))
        g_draw.add_widget(self._mk_tool(Tool.LINE_LA, "Length/Angle", Ico.line_la, BTN_IDLE))
        g_draw.add_widget(self._mk("Insert Text", Ico.text, BTN_ACTIVE, lambda: TextInsertPopup(cv).open()))
        col.add_widget(g_draw)

        col.add_widget(SectionLabel("CURVES"))
        col.add_widget(self._grid([
            (Tool.CIRCLE_CR, "Circle CR", Ico.circle_cr, BTN_IDLE),
            (Tool.CIRCLE_R,  "Circle R",  Ico.circle_r,  BTN_WARN),
            (Tool.CIRCLE_2P, "Circle 2P", Ico.circle_2p, BTN_IDLE),
            (Tool.ARC_3P,    "Arc 3P",    Ico.arc_3p,    BTN_IDLE),
        ]))

        col.add_widget(SectionLabel("SHAPE"))
        col.add_widget(self._grid([
            (Tool.RECT,    "Rectangle", Ico.rect,    BTN_IDLE),
            (Tool.POLY,    "Polygon",   Ico.poly,    BTN_IDLE),
            (Tool.MEASURE, "Measure",   Ico.measure, BTN_IDLE),
        ]))

        col.add_widget(SectionLabel("OPTS"))
        g = self._blank_grid()
        self.ortho_btn = self._mk("Ortho OFF", Ico.ortho, BTN_NEUTRAL, self._ortho)
        g.add_widget(self.ortho_btn)
        self.label_btn = self._mk("Labels: Full", Ico.labels, BTN_NEUTRAL, self._cycle_labels)
        g.add_widget(self.label_btn)
        g.add_widget(self._mk("Finish", Ico.finish, BTN_NEUTRAL, cv.finish))
        g.add_widget(self._mk("Key-in L/A", Ico.keyin, BTN_ACTIVE, lambda: KeyInPopup(cv).open()))
        g.add_widget(self._mk("Polygon sides", Ico.sides, BTN_NEUTRAL, lambda: SidesPopup(cv).open()))
        col.add_widget(g)

        col.add_widget(SectionLabel("HIST"))
        g2 = self._blank_grid()
        g2.add_widget(self._mk("Undo", Ico.undo, BTN_NEUTRAL, cv.undo))
        g2.add_widget(self._mk("Redo", Ico.redo, BTN_NEUTRAL, cv.redo))
        g2.add_widget(self._mk("Clear all", Ico.clear, BTN_DANGER, cv.clear_all))
        g2.add_widget(self._mk("Delete sel", Ico.delete, BTN_DANGER, cv.delete_selected))
        col.add_widget(g2)

        self._activate(Tool.SELECT)

    def _up_bg(self, *a):
        self._bg.pos, self._bg.size = self.pos, self.size

    def _blank_grid(self):
        g = GridLayout(cols=UI_COLS, spacing=UI_GAP, size_hint_y=None)
        g.bind(minimum_height=g.setter("height"))
        return g

    def _mk(self, name, drawer, bg, callback=None):
        btn = IconButton(name, drawer, callback=callback, bg=bg)
        btn.bind(on_press=lambda b: setattr(self.cv, "status_text", b.name))
        return btn

    def _mk_tool(self, tool, name, drawer, bg):
        btn = self._mk(name, drawer, bg)
        btn.bind(on_release=lambda _b, t=tool: self._activate(t))
        self.tool_buttons.append((btn, tool))
        return btn

    def _grid(self, spec):
        g = self._blank_grid()
        for tool, name, drawer, bg in spec:
            g.add_widget(self._mk_tool(tool, name, drawer, bg))
        return g

    def _activate(self, tool: Tool):
        self.cv.set_tool(tool)
        for btn, t in self.tool_buttons:
            btn.set_active(t is tool)

    def _set_color(self, color):
        self.cv.set_drawing_color(color)
        for btn in self.color_buttons:
            btn.set_active(btn.color_value == color)

    def _toggle_snap(self):
        self.cv.toggle_snap()
        self._sync_snap_button()
        self._sync_snap_mode_buttons()

    def _toggle_snap_mode(self, kind):
        self.cv.toggle_snap_mode(kind)
        self._sync_snap_button()
        self._sync_snap_mode_buttons()

    def _sync_snap_button(self):
        if self.cv.snap_enabled:
            self.snap_btn.text = "SNAP ON"
            self.snap_btn.bg = list(BTN_WARN)
        else:
            self.snap_btn.text = "SNAP OFF"
            self.snap_btn.bg = list(BTN_NEUTRAL)

    def _sync_snap_mode_buttons(self):
        for kind, btn in self.snap_mode_btns.items():
            on = self.cv._snap_mode_enabled(kind) and self.cv.snap_enabled
            btn.bg = list(BTN_ACTIVE if on else BTN_NEUTRAL)

    def _ortho(self):
        self.cv.toggle_ortho()
        on = self.cv.ortho
        self.ortho_btn.name = "Ortho ON" if on else "Ortho OFF"
        self.ortho_btn.idle_bg = list(BTN_WARN if on else BTN_NEUTRAL)
        self.ortho_btn.bg = list(self.ortho_btn.idle_bg)

    def _cycle_labels(self):
        m = (int(self.cv.label_mode) + 1) % 3
        self.cv.label_mode = m
        names = ("Labels OFF", "Labels: P", "Labels: Full")
        self.label_btn.name = names[m]
        self.cv.status_text = names[m]

class RibbonMenuButton(Button):
    def __init__(self, text="", bg=BTN_NEUTRAL, **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("height", dp(30))
        super().__init__(text=text, **kw)
        self.background_normal = ""
        self.background_down = ""
        self.background_disabled_normal = ""
        self.background_disabled_down = ""
        self.border = (0, 0, 0, 0)
        self.color = TEXT_MAIN
        self.font_size = kw.get("font_size", "11sp")
        self.background_color = list(bg)
        self.bind(size=self._sync_text)

    def _sync_text(self, *a):
        self.text_size = self.size

    def set_bg(self, bg):
        self.background_color = list(bg)

class RibbonShell(BoxLayout):
    def __init__(self, cv: DrawingCanvas, **kw):
        kw.setdefault("orientation", "horizontal")
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", dp(46))
        kw.setdefault("spacing", dp(6))
        kw.setdefault("padding", [dp(8), dp(8), dp(8), dp(8)])
        super().__init__(**kw)
        self.cv = cv
        self.active_menu = None
        self.last_file_choice = ""
        self.file_items = ["Open", "Save", "Save As", "Import", "Export"]

        with self.canvas.before:
            Color(0.13, 0.16, 0.21, 1)
            self._bg = Rectangle(pos=self.pos, size=self.size)
        self.bind(pos=self._sync_bg, size=self._sync_bg)

        self.file_btn = RibbonMenuButton(text="FILE", bg=BTN_WARN, width=dp(126))
        self.utility_btn = RibbonMenuButton(text="UTILITY", bg=BTN_EDIT, width=dp(126))
        self.file_btn.bind(on_release=self._open_file_menu)
        self.utility_btn.bind(on_release=self._open_utility_menu)
        self.add_widget(self.file_btn)
        self.add_widget(self.utility_btn)
        self.doc_lbl = Label(text="PY Folder", color=TEXT_DIM, font_size="9sp", halign="left", valign="middle", shorten=True, shorten_from="right")
        self.doc_lbl.bind(size=lambda w, v: setattr(w, "text_size", v))
        self.add_widget(self.doc_lbl)

        self.file_dropdown = None
        self.utility_dropdown = None
        self._sync_menu_buttons()
        Clock.schedule_interval(self._refresh_doc_label, 0.35)

    def _sync_bg(self, *a):
        self._bg.pos = self.pos
        self._bg.size = self.size

    def _refresh_doc_label(self, *_a):
        doc = self.cv._doc_display_name()
        snap_state = "OFF" if not self.cv.snap_enabled else self.cv._active_snap_modes_text()
        self.doc_lbl.text = f"{doc}  |  LAYER: {self.cv.active_layer}  |  py  |  SNAP: {snap_state}"

    def _dropdown_item(self, text="", bg=BTN_NEUTRAL, disabled=False):
        btn = RibbonMenuButton(text=text, bg=bg, width=dp(220), height=dp(32), font_size="11sp")
        btn.size_hint = (1, None)
        btn.disabled = disabled
        if disabled:
            btn.color = (0.65, 0.72, 0.80, 0.85)
        return btn

    def _decorate_dropdown(self, dd: DropDown):
        dd.auto_width = False
        dd.width = dp(220)
        dd.max_height = dp(286)
        dd.bind(on_dismiss=lambda *_: self._clear_active())
        return dd

    def _build_file_dropdown(self):
        dd = self._decorate_dropdown(DropDown())
        for label in self.file_items:
            bg = BTN_ACTIVE if self.last_file_choice == label else BTN_NEUTRAL
            btn = self._dropdown_item(label, bg=bg, disabled=False)
            btn.bind(on_release=lambda _btn, t=label: self._run_file_command(t))
            dd.add_widget(btn)
        for _ in range(2):
            dd.add_widget(self._dropdown_item(" ", bg=(0.18, 0.22, 0.28, 1), disabled=True))
        return dd

    def _build_utility_dropdown(self):
        dd = self._decorate_dropdown(DropDown())
        utility_items = [
            "Snap",
            "Snap ON/OFF",
            "Snap END",
            "Snap MID",
            "Snap INT",
            "Snap NEAR",
            "Snap CENTER",
            "Snap QUAD",
            "Snap CLOSE",
            "Undo",
            "Redo",
            "Select All",
            "Convert UTM to Geo",
            "Convert Geo to UTM",
            "Coord Table",
            "Save Cell",
            "Insert Cell",
            "Layers",
        ]
        for label in utility_items:
            btn = self._dropdown_item(label, bg=BTN_NEUTRAL, disabled=False)
            btn.bind(on_release=lambda _btn, t=label: self._run_utility_command(t))
            dd.add_widget(btn)
        dd.add_widget(self._dropdown_item(" ", bg=(0.18, 0.22, 0.28, 1), disabled=True))
        return dd

    def _sync_menu_buttons(self):
        self.file_btn.set_bg(BTN_ACTIVE if self.active_menu == "file" else BTN_WARN)
        self.utility_btn.set_bg(BTN_ACTIVE if self.active_menu == "utility" else BTN_EDIT)

    def _clear_active(self):
        self.active_menu = None
        self._sync_menu_buttons()

    def _open_file_menu(self, *_):
        self.active_menu = "file"
        self.cv.status_text = "FILE menu"
        self._sync_menu_buttons()
        if self.utility_dropdown is not None:
            self.utility_dropdown.dismiss()
        if self.file_dropdown is not None:
            self.file_dropdown.dismiss()
        self.file_dropdown = self._build_file_dropdown()
        self.file_dropdown.open(self.file_btn)

    def _open_utility_menu(self, *_):
        self.active_menu = "utility"
        self.cv.status_text = "UTILITY menu"
        self._sync_menu_buttons()
        if self.file_dropdown is not None:
            self.file_dropdown.dismiss()
        if self.utility_dropdown is not None:
            self.utility_dropdown.dismiss()
        self.utility_dropdown = self._build_utility_dropdown()
        self.utility_dropdown.open(self.utility_btn)

    def _open_coord_convert(self, mode_label: str):
        pop = CoordConvertPopup(self.cv)
        if mode_label == "Convert UTM to Geo":
            pop.geo_result.text = "Use the top section: UTM -> Geographic"
            pop.geo_result.color = STATUS_FG
        elif mode_label == "Convert Geo to UTM":
            pop.utm_result.text = "Use the bottom section: Geographic -> UTM"
            pop.utm_result.color = STATUS_FG
        pop.open()

    def _run_utility_command(self, label: str):
        if self.utility_dropdown is not None:
            self.utility_dropdown.dismiss()
        if label == "Snap":
            Clock.schedule_once(lambda _dt: SnapSettingsPopup(self.cv).open(), 0)
        elif label == "Snap ON/OFF":
            self.cv.toggle_snap()
        elif label.startswith("Snap "):
            snap_map = {
                "Snap END": "end",
                "Snap MID": "mid",
                "Snap INT": "int",
                "Snap NEAR": "near",
                "Snap CENTER": "center",
                "Snap QUAD": "quad",
                "Snap CLOSE": "close",
            }
            kind = snap_map.get(label)
            if kind:
                self.cv.toggle_snap_mode(kind)
            else:
                self.cv.status_text = f"UTILITY > {label}"
        elif label == "Undo":
            self.cv.undo()
        elif label == "Redo":
            self.cv.redo()
        elif label == "Select All":
            self.cv.select_all()
        elif label == "Convert UTM to Geo":
            Clock.schedule_once(lambda _dt: self._open_coord_convert(label), 0)
        elif label == "Convert Geo to UTM":
            Clock.schedule_once(lambda _dt: self._open_coord_convert(label), 0)
        elif label == "Coord Table":
            Clock.schedule_once(lambda _dt: CoordTablePopup(self.cv).open(), 0)
        elif label == "Save Cell":
            Clock.schedule_once(lambda _dt: SaveCellPopup(self.cv).open(), 0)
        elif label == "Insert Cell":
            Clock.schedule_once(lambda _dt: CellLibraryPopup(self.cv).open(), 0)
        elif label == "Layers":
            Clock.schedule_once(lambda _dt: LayerManagerPopup(self.cv).open(), 0)
        else:
            self.cv.status_text = f"UTILITY > {label}"

    def _run_file_command(self, label: str):
        self.last_file_choice = label
        if self.file_dropdown is not None:
            self.file_dropdown.dismiss()
        if label == "Open":
            Clock.schedule_once(lambda _dt: DrawingFileListPopup(self.cv, mode="open").open(), 0)
        elif label == "Save":
            ok, msg = self.cv.save_current_drawing()
            if ok:
                self.cv.status_text = f"Saved: {os.path.basename(msg)}"
            elif msg == "SAVE_AS_REQUIRED":
                Clock.schedule_once(lambda _dt: SaveDrawingAsPopup(self.cv, export_mode=False).open(), 0)
            else:
                self.cv.status_text = msg
        elif label == "Save As":
            Clock.schedule_once(lambda _dt: SaveDrawingAsPopup(self.cv, export_mode=False).open(), 0)
        elif label == "Import":
            Clock.schedule_once(lambda _dt: DrawingFileListPopup(self.cv, mode="import").open(), 0)
        elif label == "Export":
            Clock.schedule_once(lambda _dt: SaveDrawingAsPopup(self.cv, export_mode=True).open(), 0)
        else:
            self.cv.status_text = f"FILE > {label}"

class CollapseBar(ButtonBehavior, Widget):
    def __init__(self, panel: ToolPanel, **kw):
        kw.setdefault("size_hint_x", None)
        kw.setdefault("width", HANDLE_W)
        super().__init__(**kw)
        self.panel = panel
        self.opened = True
        with self.canvas.before:
            Color(*PANEL_BG)
            self._bg = Rectangle(pos=self.pos, size=self.size)
        self.bind(pos=self._draw, size=self._draw, on_release=self._toggle)
        self._draw()

    def _draw(self, *a):
        self._bg.pos, self._bg.size = self.pos, self.size
        self.canvas.after.clear()
        w = self.width * 0.34
        cx, cy = self.center_x, self.center_y
        sign = -1.0 if self.opened else 1.0
        with self.canvas.after:
            Color(0.45, 0.58, 0.70, 1)
            Line(points=[cx - sign * w, cy + w * 1.6,
                         cx + sign * w, cy,
                         cx - sign * w, cy - w * 1.6], width=1.4)
            Color(0.20, 0.25, 0.31, 1)
            Line(points=[self.x, self.y, self.x, self.top], width=1)

    def _toggle(self, *a):
        self.opened = not self.opened
        self.panel.width = PANEL_W if self.opened else 0
        self.panel.opacity = 1 if self.opened else 0
        self.panel.disabled = not self.opened
        self._draw()

class StatusBar(BoxLayout):
    def __init__(self, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", dp(28))
        kw.setdefault("padding", [dp(8), 0, dp(8), 0])
        super().__init__(**kw)
        with self.canvas.before:
            Color(*STATUS_BG)
            self._bg = Rectangle(pos=self.pos, size=self.size)
        self.bind(pos=self._up, size=self._up)
        self.lbl = Label(text="Ready", color=STATUS_FG, bold=True, font_size="12sp", halign="left", valign="middle", shorten=True, shorten_from="right")
        self.lbl.bind(size=lambda w, v: setattr(w, "text_size", v))
        self.add_widget(self.lbl)

    def _up(self, *a):
        self._bg.pos, self._bg.size = self.pos, self.size

class RootLayout(BoxLayout):
    def __init__(self, **kw):
        kw.setdefault("orientation", "vertical")
        super().__init__(**kw)
        self.cv = DrawingCanvas()
        self.ribbon = RibbonShell(self.cv)
        self.add_widget(self.ribbon)
        body = BoxLayout(orientation="horizontal", spacing=0)
        self.panel = ToolPanel(self.cv)
        self.handle = CollapseBar(self.panel)
        body.add_widget(self.panel)
        body.add_widget(self.handle)
        body.add_widget(self.cv)
        self.add_widget(body)
        self.bar = StatusBar()
        self.cv.bind(status_text=lambda _i, v: setattr(self.bar.lbl, "text", v))
        self.add_widget(self.bar)

class PyStationApp(App):
    def build(self):
        self.title = "p16 - Strong Rotate Fix"
        return RootLayout()

